_GITHUB_STATE_TABLE = None


def _github_state_table():
    global _GITHUB_STATE_TABLE

    if _GITHUB_STATE_TABLE is not None:
        return _GITHUB_STATE_TABLE

    if TableServiceClient is None:
        LOGGER.error(
            "azure-data-tables is not installed; "
            "durable GitHub auth state is unavailable."
        )
        return None

    table_name = (
        os.getenv("TERRABOT_GITHUB_STATE_TABLE")
        or "TerrabotGithubState"
    ).strip()

    connection_string = (
        os.getenv("TERRABOT_STATE_STORAGE_CONNECTION_STRING")
        or ""
    ).strip()

    table_service_client_cls = TableServiceClient
    if table_service_client_cls is None:
        LOGGER.error(
            "azure-data-tables is not installed; "
            "durable GitHub auth state is unavailable."
        )
        return None

    try:
        if connection_string:
            service = table_service_client_cls.from_connection_string(
                connection_string
            )
        else:
            account_url = (
                os.getenv("TERRABOT_STATE_STORAGE_ACCOUNT_URL")
                or os.getenv("AzureWebJobsStorage__tableServiceUri")
                or ""
            ).strip().rstrip("/")

            account_name = (
                os.getenv("AzureWebJobsStorage__accountName")
                or ""
            ).strip()

            if not account_url and account_name:
                account_url = (
                    f"https://{account_name}.table.core.windows.net"
                )

            if not account_url:
                raise RuntimeError(
                    "Set TERRABOT_STATE_STORAGE_ACCOUNT_URL to "
                    "https://<storage-account>.table.core.windows.net."
                )

            parsed = urlparse(account_url)

            if (
                parsed.scheme != "https"
                or not parsed.netloc
                or parsed.path not in {"", "/"}
            ):
                raise ValueError(
                    "Invalid Table Storage account URL. "
                    "Do not include the table name or another URL path."
                )

            service = table_service_client_cls(
                endpoint=account_url,
                credential=DefaultAzureCredential(),
            )

        table_client = service.create_table_if_not_exists(
            table_name=table_name
        )

        _GITHUB_STATE_TABLE = table_client

        LOGGER.info(
            "Durable Teams GitHub auth table is ready: "
            "endpoint=%s table=%s",
            service.url,
            table_name,
        )

        return _GITHUB_STATE_TABLE

    except Exception:
        LOGGER.exception(
            "Unable to initialize durable Teams GitHub auth storage."
        )
        return None


def _github_state_row_key(user_key: str) -> str:
    return hashlib.sha256((user_key or "").encode("utf-8")).hexdigest()


def teams_github_conversation_key(conversation_id: str) -> str:
    conversation_id = (conversation_id or "").strip()
    return f"conversation:{conversation_id}" if conversation_id else ""


def _load_durable_github_state(user_key: str) -> dict:
    key = (user_key or "").strip()
    if not key:
        return {}
    table = _github_state_table()
    if table is None:
        return {}
    try:
        entity = table.get_entity("teams-github", _github_state_row_key(key))
        return dict(entity)
    except Exception as exc:
        if "ResourceNotFound" not in type(exc).__name__:
            LOGGER.warning("Could not read durable Teams GitHub state: %s", exc)
        return {}


def _save_durable_github_state(user_key: str, values: dict) -> bool:
    key = (user_key or "").strip()
    if not key:
        return False
    table = _github_state_table()
    if table is None:
        LOGGER.error("Durable Teams GitHub state storage is unavailable.")
        return False
    update_mode = UpdateMode
    if update_mode is None:
        LOGGER.error("azure-data-tables UpdateMode is unavailable.")
        return False
    entity = {
        "PartitionKey": "teams-github",
        "RowKey": _github_state_row_key(key),
        "user_key": key,
        **{k: v for k, v in (values or {}).items() if v is not None},
    }
    try:
        table.upsert_entity(entity=entity, mode=update_mode.MERGE)
        stored = table.get_entity("teams-github", _github_state_row_key(key))
        return bool(stored)
    except Exception:
        LOGGER.exception("Unable to persist durable Teams GitHub auth state.")
        return False


def _delete_durable_github_state(user_key: str) -> None:
    key = (user_key or "").strip()
    table = _github_state_table()
    if not key or table is None:
        return
    try:
        table.delete_entity("teams-github", _github_state_row_key(key))
    except Exception:
        pass


# Teams conversation/workflow state must survive Azure Functions worker changes,
# cold starts, and scale-out. The same Azure Table account already used for
# GitHub auth state is reused, but the data is isolated by partition.
_TEAMS_CONVERSATION_STATE_PARTITION = "teams-conversation-state"
_TEAMS_WORKFLOW_STATE_PARTITION = "teams-workflow-state"
_TEAMS_STATE_SCHEMA_VERSION = 1
_TEAMS_STATE_CHUNK_SIZE = max(
    8_000,
    min(int(os.getenv("TERRABOT_TEAMS_STATE_CHUNK_SIZE", "28000")), 30_000),
)
_TEAMS_STATE_MAX_CHUNKS = max(
    8,
    min(int(os.getenv("TERRABOT_TEAMS_STATE_MAX_CHUNKS", "128")), 256),
)
_TEAMS_STATE_TTL_SECONDS = max(
    3_600,
    int(os.getenv("TERRABOT_TEAMS_STATE_TTL_SECONDS", str(7 * 24 * 60 * 60))),
)
_TEAMS_STATE_LOCK = threading.RLock()


def _teams_state_json_safe(value):
    """Convert workflow state to JSON-safe primitives without losing structure."""
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {
            str(key): _teams_state_json_safe(item)
            for key, item in value.items()
        }
    if isinstance(value, (list, tuple, set)):
        return [_teams_state_json_safe(item) for item in value]
    if isinstance(value, datetime):
        return value.astimezone(timezone.utc).isoformat()
    return str(value)


def _teams_state_base_row_key(state_key: str) -> str:
    return hashlib.sha256((state_key or "").encode("utf-8")).hexdigest()


def _teams_state_chunk_row_key(
    base_row_key: str,
    generation: str,
    index: int,
) -> str:
    generation = re.sub(r"[^A-Za-z0-9-]", "", generation or "legacy")[:24] or "legacy"
    return f"{base_row_key}-{generation}-c{int(index):04d}"


def _encode_teams_state_payload(payload: dict) -> tuple[list[str], str]:
    raw = json.dumps(
        _teams_state_json_safe(payload or {}),
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    encoded = base64.b64encode(zlib.compress(raw, level=9)).decode("ascii")
    chunks = [
        encoded[index:index + _TEAMS_STATE_CHUNK_SIZE]
        for index in range(0, len(encoded), _TEAMS_STATE_CHUNK_SIZE)
    ] or [""]
    if len(chunks) > _TEAMS_STATE_MAX_CHUNKS:
        raise ValueError(
            "Teams workflow state is too large for durable Table Storage "
            f"({len(chunks)} chunks; maximum {_TEAMS_STATE_MAX_CHUNKS})."
        )
    checksum = hashlib.sha256(encoded.encode("ascii")).hexdigest()
    return chunks, checksum


def _decode_teams_state_payload(encoded: str, checksum: str = "") -> dict:
    encoded = str(encoded or "")
    if checksum:
        actual = hashlib.sha256(encoded.encode("ascii")).hexdigest()
        if actual != checksum:
            raise ValueError("Durable Teams state checksum validation failed.")
    raw = zlib.decompress(base64.b64decode(encoded.encode("ascii")))
    payload = json.loads(raw.decode("utf-8"))
    return payload if isinstance(payload, dict) else {}


def _load_chunked_teams_state(partition_key: str, state_key: str) -> dict:
    key = (state_key or "").strip()
    if not key:
        return {}
    table = _github_state_table()
    if table is None:
        return {}

    base_row_key = _teams_state_base_row_key(key)
    try:
        metadata = dict(table.get_entity(partition_key, base_row_key))
    except Exception as exc:
        if "ResourceNotFound" not in type(exc).__name__:
            LOGGER.warning(
                "Could not read durable Teams state partition=%s key_hash=%s: %s",
                partition_key,
                base_row_key[:12],
                exc,
            )
        return {}

    expires_at = float(metadata.get("expires_at_epoch") or 0)
    if expires_at and time.time() > expires_at:
        _delete_chunked_teams_state(partition_key, key)
        return {}

    chunk_count = int(metadata.get("chunk_count") or 0)
    if chunk_count <= 0 or chunk_count > _TEAMS_STATE_MAX_CHUNKS:
        LOGGER.error(
            "Invalid durable Teams state chunk count partition=%s key_hash=%s count=%s",
            partition_key,
            base_row_key[:12],
            chunk_count,
        )
        return {}

    generation = str(metadata.get("generation") or "legacy").strip() or "legacy"
    chunks = []
    try:
        for index in range(chunk_count):
            entity = table.get_entity(
                partition_key,
                _teams_state_chunk_row_key(base_row_key, generation, index),
            )
            chunks.append(str(entity.get("payload") or ""))
        return _decode_teams_state_payload(
            "".join(chunks),
            str(metadata.get("checksum") or ""),
        )
    except Exception:
        LOGGER.exception(
            "Unable to decode durable Teams state partition=%s key_hash=%s",
            partition_key,
            base_row_key[:12],
        )
        return {}


def _save_chunked_teams_state(partition_key: str, state_key: str, payload: dict) -> bool:
    key = (state_key or "").strip()
    if not key:
        return False
    table = _github_state_table()
    if table is None:
        LOGGER.error(
            "Durable Teams state storage is unavailable. Configure Table Storage "
            "before running Teams multi-turn workflows in production."
        )
        return False
    update_mode = UpdateMode
    if update_mode is None:
        LOGGER.error("azure-data-tables UpdateMode is unavailable.")
        return False

    try:
        chunks, checksum = _encode_teams_state_payload(payload)
    except Exception:
        LOGGER.exception("Unable to serialize durable Teams state.")
        return False

    base_row_key = _teams_state_base_row_key(key)
    now = time.time()
    replace_mode = update_mode.REPLACE

    with _TEAMS_STATE_LOCK:
        old_chunk_count = 0
        old_generation = ""
        try:
            old = table.get_entity(partition_key, base_row_key)
            old_chunk_count = int(old.get("chunk_count") or 0)
            old_generation = str(old.get("generation") or "legacy").strip() or "legacy"
        except Exception:
            old_chunk_count = 0
            old_generation = ""

        generation = uuid.uuid4().hex[:16]
        try:
            for index, chunk in enumerate(chunks):
                table.upsert_entity(
                    entity={
                        "PartitionKey": partition_key,
                        "RowKey": _teams_state_chunk_row_key(base_row_key, generation, index),
                        "payload": chunk,
                    },
                    mode=replace_mode,
                )

            # Metadata is written last. Readers continue using the complete old
            # generation until this atomic entity replacement points them to
            # the complete new generation.
            table.upsert_entity(
                entity={
                    "PartitionKey": partition_key,
                    "RowKey": base_row_key,
                    "state_key": key,
                    "schema_version": _TEAMS_STATE_SCHEMA_VERSION,
                    "generation": generation,
                    "chunk_count": len(chunks),
                    "checksum": checksum,
                    "updated_at_epoch": now,
                    "expires_at_epoch": now + _TEAMS_STATE_TTL_SECONDS,
                },
                mode=replace_mode,
            )

            if old_generation:
                for index in range(min(old_chunk_count, _TEAMS_STATE_MAX_CHUNKS)):
                    try:
                        table.delete_entity(
                            partition_key,
                            _teams_state_chunk_row_key(base_row_key, old_generation, index),
                        )
                    except Exception:
                        pass
            return True
        except Exception:
            LOGGER.exception(
                "Unable to persist durable Teams state partition=%s key_hash=%s",
                partition_key,
                base_row_key[:12],
            )
            return False


def _delete_chunked_teams_state(partition_key: str, state_key: str) -> None:
    key = (state_key or "").strip()
    table = _github_state_table()
    if not key or table is None:
        return
    base_row_key = _teams_state_base_row_key(key)
    chunk_count = 0
    generation = "legacy"
    try:
        metadata = table.get_entity(partition_key, base_row_key)
        chunk_count = int(metadata.get("chunk_count") or 0)
        generation = str(metadata.get("generation") or "legacy").strip() or "legacy"
    except Exception:
        chunk_count = 0
    for index in range(min(chunk_count, _TEAMS_STATE_MAX_CHUNKS)):
        try:
            table.delete_entity(
                partition_key,
                _teams_state_chunk_row_key(base_row_key, generation, index),
            )
        except Exception:
            pass
    try:
        table.delete_entity(partition_key, base_row_key)
    except Exception:
        pass


def load_teams_conversation_state(teams_conversation_id: str) -> dict:
    """Load durable UI/router state for one Microsoft Teams conversation."""
    return _load_chunked_teams_state(
        _TEAMS_CONVERSATION_STATE_PARTITION,
        (teams_conversation_id or "").strip(),
    )


def save_teams_conversation_state(teams_conversation_id: str, state: dict) -> bool:
    """Persist non-secret Teams state used to route follow-up messages."""
    cleaned = {
        str(key): value
        for key, value in dict(state or {}).items()
        if "token" not in str(key).lower() and "secret" not in str(key).lower()
    }
    return _save_chunked_teams_state(
        _TEAMS_CONVERSATION_STATE_PARTITION,
        (teams_conversation_id or "").strip(),
        cleaned,
    )


def clear_teams_conversation_state(teams_conversation_id: str) -> None:
    _delete_chunked_teams_state(
        _TEAMS_CONVERSATION_STATE_PARTITION,
        (teams_conversation_id or "").strip(),
    )


def _reset_teams_chat_session_base(
    teams_conversation_id: str,
    workflow_thread_id: str = "",
) -> dict:
    """Clear Teams router/workflow state without deleting GitHub artifacts or auth."""
    conversation_id = (teams_conversation_id or "").strip()
    thread_id = (workflow_thread_id or "").strip()

    if thread_id:
        THREAD_PR_STATE.pop(thread_id, None)
        THREAD_METADATA.pop(thread_id, None)
        THREAD_AUTO_ADVANCE_IN_PROGRESS.discard(thread_id)
        for mapping in _teams_pending_state_mappings().values():
            _remove_teams_mapping_entries_for_thread(mapping, thread_id)
        _delete_chunked_teams_state(_TEAMS_WORKFLOW_STATE_PARTITION, thread_id)

    if conversation_id:
        clear_teams_conversation_state(conversation_id)

    LOGGER.info(
        "Reset Teams chat session: conversation_hash=%s workflow_thread_hash=%s",
        stable_thread_key(conversation_id) if conversation_id else "",
        stable_thread_key(thread_id) if thread_id else "",
    )
    return {
        "ok": True,
        "conversation_state_cleared": bool(conversation_id),
        "workflow_state_cleared": bool(thread_id),
        "github_artifacts_deleted": False,
        "github_auth_cleared": False,
    }


def _teams_pending_state_mappings() -> dict[str, dict]:
    return {
        "pending_infra_changes": PENDING_INFRA_CHANGES,
        "pending_cloud_clarifications": PENDING_CLOUD_CLARIFICATIONS,
        "pending_aws_module_discoveries": PENDING_AWS_MODULE_DISCOVERIES,
        "pending_azure_module_discoveries": azure_workflow_state.PENDING_AZURE_MODULE_DISCOVERIES,
        "pending_azure_consumer_value_selections": PENDING_AZURE_CONSUMER_VALUE_SELECTIONS,
        "pending_azure_new_consumer_file_confirmations": PENDING_AZURE_NEW_CONSUMER_FILE_CONFIRMATIONS,
        "pending_module_variable_value_selections": PENDING_MODULE_VARIABLE_VALUE_SELECTIONS,
        "pending_infra_modification_selections": PENDING_INFRA_MODIFICATION_SELECTIONS,
    }


def _teams_mapping_entries_for_thread(mapping: dict, thread_id: str) -> dict:
    thread = str(thread_id or "")
    return {
        str(key): value
        for key, value in mapping.items()
        if isinstance(value, dict)
        and str(value.get("thread_id") or "") == thread
    }


def _remove_teams_mapping_entries_for_thread(mapping: dict, thread_id: str) -> None:
    thread = str(thread_id or "")
    for key, value in list(mapping.items()):
        if isinstance(value, dict) and str(value.get("thread_id") or "") == thread:
            mapping.pop(key, None)


def capture_teams_workflow_state(thread_id: str) -> dict:
    """Capture every backend pending object belonging to one Teams thread."""
    thread = (thread_id or "").strip()
    if not thread:
        return {}
    return {
        "schema_version": _TEAMS_STATE_SCHEMA_VERSION,
        "thread_id": thread,
        "thread_pr_state": _teams_state_json_safe(THREAD_PR_STATE.get(thread) or {}),
        "pending": {
            name: _teams_state_json_safe(
                _teams_mapping_entries_for_thread(mapping, thread)
            )
            for name, mapping in _teams_pending_state_mappings().items()
        },
    }


def persist_teams_workflow_state(thread_id: str) -> bool:
    """Persist backend workflow/pending state after every Teams turn."""
    thread = (thread_id or "").strip()
    if not thread:
        return False
    return _save_chunked_teams_state(
        _TEAMS_WORKFLOW_STATE_PARTITION,
        thread,
        capture_teams_workflow_state(thread),
    )


def restore_teams_workflow_state(thread_id: str) -> bool:
    """Restore backend workflow state before processing a Teams follow-up."""
    thread = (thread_id or "").strip()
    if not thread:
        return False
    snapshot = _load_chunked_teams_state(_TEAMS_WORKFLOW_STATE_PARTITION, thread)
    if not snapshot:
        return False

    thread_pr_state = snapshot.get("thread_pr_state")
    if isinstance(thread_pr_state, dict):
        THREAD_PR_STATE[thread] = thread_pr_state

    pending_snapshot = snapshot.get("pending") or {}
    for name, mapping in _teams_pending_state_mappings().items():
        _remove_teams_mapping_entries_for_thread(mapping, thread)
        restored = pending_snapshot.get(name) or {}
        if isinstance(restored, dict):
            mapping.update(restored)

    LOGGER.info(
        "Restored durable Teams workflow state: thread_hash=%s pending_groups=%s",
        stable_thread_key(thread),
        sum(bool(items) for items in pending_snapshot.values() if isinstance(items, dict)),
    )
    return True


def teams_workflow_has_pending_state(thread_id: str) -> bool:
    thread = (thread_id or "").strip()
    if not thread:
        return False
    for mapping in _teams_pending_state_mappings().values():
        if _teams_mapping_entries_for_thread(mapping, thread):
            return True
    return False


def teams_github_user_key(tenant_id: str, aad_object_id: str) -> str:
    tenant = (tenant_id or "").strip()
    user = (aad_object_id or "").strip()
    if not tenant or not user:
        return ""
    return f"{tenant}:{user}"


def get_teams_github_token(user_key: str) -> str:
    key = (user_key or "").strip()
    token = (TEAMS_GITHUB_TOKENS.get(key) or "").strip()
    if token:
        return token
    durable = _load_durable_github_state(key)
    token = str(durable.get("access_token") or "").strip()
    if token:
        TEAMS_GITHUB_TOKENS[key] = token
    return token


def set_teams_github_token(user_key: str, token: str) -> None:
    key = (user_key or "").strip()
    value = (token or "").strip()
    if not key or not value:
        raise ValueError("A Teams GitHub user key and token are required.")
    TEAMS_GITHUB_TOKENS[key] = value
    _save_durable_github_state(key, {
        "access_token": value,
        "auth_status": "connected",
        "device_code": "",
        "user_code": "",
        "pending_prompt": "",
    })


def clear_teams_github_token(user_key: str) -> None:
    key = (user_key or "").strip()
    TEAMS_GITHUB_TOKENS.pop(key, None)
    TEAMS_GITHUB_DEVICE_STATE.pop(key, None)
    _delete_durable_github_state(key)

def _github_oauth_client_id() -> str:
    """Resolve the GitHub OAuth client used by VS Code/Teams integrations."""
    for name in (
        "GITHUB_OAUTH_CLIENT_ID",
        "GITHUB_CLIENT_ID",
        "TERRABOT_GITHUB_CLIENT_ID",
        "VSCODE_GITHUB_CLIENT_ID",
    ):
        value = (os.getenv(name) or "").strip()
        if value:
            return value
    return ""


def _github_oauth_client_secret() -> str:
    for name in (
        "GITHUB_OAUTH_CLIENT_SECRET",
        "GITHUB_CLIENT_SECRET",
        "TERRABOT_GITHUB_CLIENT_SECRET",
        "VSCODE_GITHUB_CLIENT_SECRET",
    ):
        value = (os.getenv(name) or "").strip()
        if value:
            return value
    return ""


def _github_oauth_callback_url() -> str:
    callback_url = (os.getenv("GITHUB_OAUTH_CALLBACK_URL") or "").strip()
    public_base = (os.getenv("TERRABOT_PUBLIC_BASE_URL") or "").strip().rstrip("/")
    return callback_url or (f"{public_base}/api/github/teams/callback" if public_base else "")


def build_teams_github_connect_url(user_key: str, conversation_id: str = "") -> str:
    """Build browser OAuth URL when a callback-based OAuth app is configured."""
    client_id = _github_oauth_client_id()
    callback_url = _github_oauth_callback_url()
    if not client_id:
        raise RuntimeError(
            "Missing GitHub OAuth client ID. Configure one of "
            "GITHUB_OAUTH_CLIENT_ID, GITHUB_CLIENT_ID, "
            "TERRABOT_GITHUB_CLIENT_ID, or VSCODE_GITHUB_CLIENT_ID."
        )
    if not callback_url:
        raise RuntimeError("Missing GITHUB_OAUTH_CALLBACK_URL or TERRABOT_PUBLIC_BASE_URL.")

    nonce = uuid.uuid4().hex
    TEAMS_GITHUB_OAUTH_STATE[nonce] = {
        "user_key": (user_key or "").strip(),
        "conversation_id": (conversation_id or "").strip(),
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    scopes = (os.getenv("GITHUB_OAUTH_SCOPES") or "repo read:org").strip()
    return "https://github.com/login/oauth/authorize?" + urlencode({
        "client_id": client_id,
        "redirect_uri": callback_url,
        "scope": scopes,
        "state": nonce,
    })


def start_teams_github_authentication(user_key: str, conversation_id: str = "", pending_prompt: str = "") -> dict:
    """Start GitHub auth using browser OAuth or GitHub's device flow.

    Device flow mirrors the VS Code experience more closely: the user opens
    GitHub, enters a short code, and no Function App client secret or public
    callback route is required. The GitHub OAuth app must have Device Flow
    enabled.
    """
    client_id = _github_oauth_client_id()
    if not client_id:
        raise RuntimeError(
            "Missing GitHub OAuth client ID. Reuse the client ID configured for "
            "the VS Code GitHub connection by setting GITHUB_CLIENT_ID or "
            "VSCODE_GITHUB_CLIENT_ID in the Function App."
        )

    callback_url = _github_oauth_callback_url()
    client_secret = _github_oauth_client_secret()
    force_device = (os.getenv("GITHUB_OAUTH_USE_DEVICE_FLOW") or "").strip().lower() in {
        "1", "true", "yes"
    }

    if callback_url and client_secret and not force_device:
        return {
            "method": "authorization_code",
            "connect_url": build_teams_github_connect_url(user_key, conversation_id),
        }

    scopes = (os.getenv("GITHUB_OAUTH_SCOPES") or "repo read:org").strip()
    response = requests.post(
        "https://github.com/login/device/code",
        headers={"Accept": "application/json"},
        data={"client_id": client_id, "scope": scopes},
        timeout=30,
    )
    if not response.ok:
        raise _github_request_error(response, "Starting GitHub device authentication")
    payload = response.json() or {}
    device_code = str(payload.get("device_code") or "").strip()
    user_code = str(payload.get("user_code") or "").strip()
    verification_uri = str(
        payload.get("verification_uri")
        or payload.get("verification_uri_complete")
        or "https://github.com/login/device"
    ).strip()
    if not device_code or not user_code:
        raise RuntimeError("GitHub did not return a device authentication code.")

    key = (user_key or "").strip()
    device_state = {
        "device_code": device_code,
        "user_code": user_code,
        "verification_uri": verification_uri,
        "conversation_id": (conversation_id or "").strip(),
        "pending_prompt": (pending_prompt or "").strip(),
        "interval": max(5, int(payload.get("interval") or 5)),
        "expires_in": int(payload.get("expires_in") or 900),
        "created_at_epoch": datetime.now(timezone.utc).timestamp(),
        "auth_status": "pending",
    }
    if not key:
        raise RuntimeError(
            "Teams could not resolve a stable GitHub user identity from the activity. "
            "The Teams tenant ID and sender AAD object ID are required."
        )

    TEAMS_GITHUB_DEVICE_STATE[key] = device_state
    saved_user_state = _save_durable_github_state(key, device_state)

    # Mirror the pending challenge under the stable Teams conversation ID.
    # Some Teams activities expose a different sender-id shape on the follow-up
    # message. The conversation key allows `continue` to recover the exact same
    # device challenge without starting a second authentication flow.
    conversation_key = teams_github_conversation_key(conversation_id)
    saved_conversation_state = False
    if conversation_key:
        TEAMS_GITHUB_DEVICE_STATE[conversation_key] = dict(device_state)
        saved_conversation_state = _save_durable_github_state(conversation_key, device_state)

    if not saved_user_state and not saved_conversation_state:
        TEAMS_GITHUB_DEVICE_STATE.pop(key, None)
        if conversation_key:
            TEAMS_GITHUB_DEVICE_STATE.pop(conversation_key, None)
        raise RuntimeError(
            "Terrabot could not persist the GitHub device challenge. Configure a reachable "
            "Azure Table Storage account and grant the Function App Storage Table Data "
            "Contributor access before retrying."
        )

    LOGGER.info(
        "Stored Teams GitHub device challenge: user_key_hash=%s conversation_key_hash=%s durable=%s",
        _github_state_row_key(key)[:12],
        _github_state_row_key(conversation_key)[:12] if conversation_key else "",
        _github_state_table() is not None,
    )
    return {
        "method": "device_flow",
        "verification_uri": verification_uri,
        "user_code": user_code,
        "expires_in": int(payload.get("expires_in") or 900),
    }


def complete_teams_github_device_authentication(
    user_key: str,
    conversation_id: str = "",
) -> dict:
    user_key = (user_key or "").strip()
    conversation_key = teams_github_conversation_key(conversation_id)

    lookup_keys = []
    for candidate in (user_key, conversation_key):
        if candidate and candidate not in lookup_keys:
            lookup_keys.append(candidate)

    state = {}
    state_key = ""
    for candidate in lookup_keys:
        state = (
            TEAMS_GITHUB_DEVICE_STATE.get(candidate)
            or _load_durable_github_state(candidate)
            or {}
        )
        if state and state.get("device_code"):
            state_key = candidate
            TEAMS_GITHUB_DEVICE_STATE[candidate] = dict(state)
            break

    if not state:
        LOGGER.warning(
            "No Teams GitHub device challenge found: user_key_hash=%s "
            "conversation_key_hash=%s durable=%s",
            _github_state_row_key(user_key)[:12] if user_key else "",
            _github_state_row_key(conversation_key)[:12] if conversation_key else "",
            _github_state_table() is not None,
        )
        return {
            "ok": False,
            "pending": False,
            "error": (
                "No GitHub device authentication is pending. The pending device "
                "challenge was not found in durable storage."
            ),
        }

    created = float(state.get("created_at_epoch") or 0)
    expires_in = int(state.get("expires_in") or 900)
    if created and datetime.now(timezone.utc).timestamp() > created + expires_in:
        for candidate in lookup_keys:
            TEAMS_GITHUB_DEVICE_STATE.pop(candidate, None)
        return {
            "ok": False,
            "pending": False,
            "error": "The GitHub device code expired. Start the connection again.",
        }

    response = requests.post(
        "https://github.com/login/oauth/access_token",
        headers={"Accept": "application/json"},
        data={
            "client_id": _github_oauth_client_id(),
            "device_code": state.get("device_code") or "",
            "grant_type": "urn:ietf:params:oauth:grant-type:device_code",
        },
        timeout=30,
    )
    if not response.ok:
        raise _github_request_error(response, "Completing GitHub device authentication")

    payload = response.json() or {}
    token = str(payload.get("access_token") or "").strip()
    error = str(payload.get("error") or "").strip()

    if token:
        pending_prompt = str(state.get("pending_prompt") or "").strip()

        # Persist the token under the canonical user key and the conversation
        # fallback key. Return the token directly so the current request does
        # not depend on a second storage read.
        if user_key:
            set_teams_github_token(user_key, token)
        if conversation_key:
            TEAMS_GITHUB_TOKENS[conversation_key] = token
            _save_durable_github_state(conversation_key, {
                "access_token": token,
                "auth_status": "connected",
                "device_code": "",
                "user_code": "",
                "pending_prompt": "",
            })

        for candidate in lookup_keys:
            TEAMS_GITHUB_DEVICE_STATE.pop(candidate, None)

        LOGGER.info(
            "Completed Teams GitHub device authentication: state_key_hash=%s "
            "user_key_hash=%s conversation_key_hash=%s",
            _github_state_row_key(state_key)[:12] if state_key else "",
            _github_state_row_key(user_key)[:12] if user_key else "",
            _github_state_row_key(conversation_key)[:12] if conversation_key else "",
        )
        return {
            "ok": True,
            "pending": False,
            "scope": payload.get("scope") or "",
            "pending_prompt": pending_prompt,
            "access_token": token,
        }

    if error in {"authorization_pending", "slow_down"}:
        return {"ok": False, "pending": True, "error": error}

    for candidate in lookup_keys:
        TEAMS_GITHUB_DEVICE_STATE.pop(candidate, None)
    return {
        "ok": False,
        "pending": False,
        "error": payload.get("error_description") or error or "GitHub authentication failed.",
    }


def handle_teams_github_oauth_callback(code: str, state: str) -> dict:
    oauth_state = TEAMS_GITHUB_OAUTH_STATE.pop((state or "").strip(), None)
    if not oauth_state:
        raise ValueError("The GitHub authentication request is invalid or expired.")
    client_id = _github_oauth_client_id()
    client_secret = _github_oauth_client_secret()
    callback_url = _github_oauth_callback_url()
    if not client_id or not client_secret:
        raise RuntimeError("GitHub OAuth client settings are incomplete.")
    response = requests.post(
        "https://github.com/login/oauth/access_token",
        headers={"Accept": "application/json"},
        data={
            "client_id": client_id,
            "client_secret": client_secret,
            "code": (code or "").strip(),
            "redirect_uri": callback_url,
            "state": (state or "").strip(),
        },
        timeout=30,
    )
    if not response.ok:
        raise _github_request_error(response, "Exchanging the GitHub OAuth code")
    payload = response.json() or {}
    token = (payload.get("access_token") or "").strip()
    if not token:
        raise RuntimeError(payload.get("error_description") or "GitHub did not return an access token.")
    set_teams_github_token(oauth_state.get("user_key") or "", token)
    return {
        "ok": True,
        "user_key": oauth_state.get("user_key") or "",
        "conversation_id": oauth_state.get("conversation_id") or "",
        "scope": payload.get("scope") or "",
    }



def _github_app_private_key() -> str:
    value = (GITHUB_APP_PRIVATE_KEY or "").strip()
    if value:
        # Azure App Settings commonly preserve line breaks as literal \\n.
        return value.replace("\\n", "\n")
    if GITHUB_APP_PRIVATE_KEY_PATH:
        with open(GITHUB_APP_PRIVATE_KEY_PATH, "r", encoding="utf-8") as handle:
            return handle.read().strip()
    raise RuntimeError(
        "Missing GitHub App private key. Set GITHUB_APP_PRIVATE_KEY to a Key Vault-backed PEM value "
        "or set GITHUB_APP_PRIVATE_KEY_PATH to a mounted secret file."
    )


def validate_github_app_settings() -> None:
    missing = []
    if not GITHUB_APP_ID:
        missing.append("GITHUB_APP_ID")
    if not GITHUB_APP_INSTALLATION_ID:
        missing.append("GITHUB_APP_INSTALLATION_ID")
    if not GITHUB_APP_PRIVATE_KEY and not GITHUB_APP_PRIVATE_KEY_PATH:
        missing.append("GITHUB_APP_PRIVATE_KEY or GITHUB_APP_PRIVATE_KEY_PATH")
    if missing:
        raise RuntimeError("Missing GitHub App setting(s): " + ", ".join(missing))


def _github_app_jwt() -> str:
    validate_github_app_settings()
    if jwt is None:
        raise RuntimeError(
            "PyJWT is required only when GitHub App authentication is enabled. "
            "Add PyJWT[crypto] to requirements.txt or disable the GitHub App settings."
        )
    now = int(time.time())
    payload = {
        "iat": now - 60,
        "exp": now + (9 * 60),
        "iss": GITHUB_APP_ID,
    }
    encoded: Any = jwt.encode(payload, _github_app_private_key(), algorithm="RS256")
    if isinstance(encoded, bytes):
        return encoded.decode("utf-8")
    return str(encoded)


def get_github_app_installation_token(force_refresh: bool = False) -> str:
    """Return a cached, short-lived installation token for Teams GitHub calls."""
    now = time.time()
    cached = str(_GITHUB_APP_TOKEN_CACHE.get("token") or "").strip()
    expires_at = float(_GITHUB_APP_TOKEN_CACHE.get("expires_at") or 0)
    if not force_refresh and cached and now < expires_at - 300:
        return cached

    with _GITHUB_APP_TOKEN_LOCK:
        now = time.time()
        cached = str(_GITHUB_APP_TOKEN_CACHE.get("token") or "").strip()
        expires_at = float(_GITHUB_APP_TOKEN_CACHE.get("expires_at") or 0)
        if not force_refresh and cached and now < expires_at - 300:
            return cached

        response = requests.post(
            f"{GITHUB_API}/app/installations/{GITHUB_APP_INSTALLATION_ID}/access_tokens",
            headers={
                "Authorization": f"Bearer {_github_app_jwt()}",
                "Accept": "application/vnd.github+json",
                "X-GitHub-Api-Version": "2022-11-28",
            },
            timeout=30,
        )
        if not response.ok:
            raise _github_request_error(response, "Creating a GitHub App installation token")

        payload = response.json() or {}
        token = str(payload.get("token") or "").strip()
        if not token:
            raise RuntimeError("GitHub did not return an installation access token.")

        expires_text = str(payload.get("expires_at") or "").strip()
        try:
            expires_epoch = datetime.fromisoformat(expires_text.replace("Z", "+00:00")).timestamp()
        except Exception:
            expires_epoch = now + 3300

        _GITHUB_APP_TOKEN_CACHE.update({"token": token, "expires_at": expires_epoch})
        return token


def validate_github_app_repository_access() -> None:
    """Fail at startup/request time if the installation lacks required repositories or write permissions."""
    token = get_github_app_installation_token()
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
    }
    for repo in (GITHUB_AWS_REPO, GITHUB_AZURE_REPO):
        if not repo:
            continue
        response = requests.get(f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}", headers=headers, timeout=30)
        if not response.ok:
            raise _github_request_error(response, f"Validating GitHub App access to {GITHUB_OWNER}/{repo}")
        permissions = (response.json() or {}).get("permissions") or {}
        if not (permissions.get("push") or permissions.get("maintain") or permissions.get("admin")):
            raise PermissionError(
                f"The GitHub App can read {GITHUB_OWNER}/{repo}, but cannot push branches. "
                "Grant repository Contents: Read and write."
            )


class teams_requester_context:
    def __init__(self, requester: str):
        self.display_name = str(requester or "Terrabot").strip() or "Terrabot"
        value = re.sub(r"[^A-Za-z0-9-]+", "-", self.display_name).strip("-").lower()
        self.requester = value[:40] or "terrabot"
        self._reset = None
        self._display_reset = None

    def __enter__(self):
        self._reset = _ACTIVE_TEAMS_REQUESTER.set(self.requester)
        self._display_reset = _ACTIVE_TEAMS_REQUESTER_DISPLAY.set(self.display_name)
        return self

    def __exit__(self, exc_type, exc, tb):
        if self._display_reset is not None:
            _ACTIVE_TEAMS_REQUESTER_DISPLAY.reset(self._display_reset)
        if self._reset is not None:
            _ACTIVE_TEAMS_REQUESTER.reset(self._reset)


class github_token_context:
    def __init__(self, token: str):
        self.token = (token or "").strip()
        self._reset = None

    def __enter__(self):
        self._reset = _ACTIVE_GITHUB_TOKEN.set(self.token)
        return self

    def __exit__(self, exc_type, exc, tb):
        if self._reset is not None:
            _ACTIVE_GITHUB_TOKEN.reset(self._reset)


# Backend-only retrieval mode. Terrabot does not use caller-provided RAG/KB
# snippets as authoritative Terraform state. Repo/module/value/resource context
# must be generated by backend live GitHub reads.
DISABLE_EXTERNAL_RAG_CONTEXT = os.getenv("TERRABOT_DISABLE_EXTERNAL_RAG_CONTEXT", "true").strip().lower() not in {"0", "false", "no"}
BACKEND_CONTEXT_SOURCE_PREFIXES = (
    "backend_",
    "live_github_",
    "github_",
    "verified_",
    "deterministic_",
)

@dataclass
class NormalizedRouterDecision:
    request_type: str
    cloud: Optional[str] = None
    workflow: str = "standard"
    reason: str = ""


class ModuleVariableValuesRequired(ValueError):
    """Raised when generated module variable files need user-approved values.

    This is intentionally not treated as a terminal backend error. The chat
    handler converts it into a module_variable_values response so the UI can
    collect approved values/references and then continue to PR preview.
    """

    def __init__(self, files: list[dict], issues: list[str], workflow: str = ""):
        super().__init__(
            "Generated module variable declarations require user-approved values. "
            + "; ".join(issues or [])
        )
        self.files = list(files or [])
        self.issues = list(issues or [])
        self.workflow = workflow or ""

def validate_foundry_settings() -> None:
    missing = []

    if not PROJECT_ENDPOINT:
        missing.append("PROJECT_ENDPOINT_STRING")

    if not AGENT_NAME:
        missing.append("AZURE_AGENT_NAME")

    if missing:
        raise ValueError(
            "Missing Foundry environment variables: "
            + ", ".join(missing)
        )


def _require_setting(value: Optional[str], name: str) -> str:
    normalized = (value or "").strip()
    if not normalized:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return normalized


def validate_github_settings() -> None:
    missing = []

    github_token = (
        GITHUB_TOKEN
        or os.getenv("TERRABOT_GITHUB_TOKEN")
        or os.getenv("GH_TOKEN")
        or ""
    ).strip()

    if not github_token:
        missing.append("GITHUB_TOKEN")

    if not GITHUB_OWNER:
        missing.append("GITHUB_OWNER")

    if not GITHUB_AWS_REPO:
        missing.append("GITHUB_AWS_REPO")

    if not GITHUB_AZURE_REPO:
        missing.append("GITHUB_AZURE_REPO")

    if not GITHUB_VENA_REPO:
        missing.append("GITHUB_VENA_REPO")

    if missing:
        raise ValueError(
            "Missing GitHub environment variables: "
            + ", ".join(missing)
        )

def get_project_client() -> AIProjectClient:
    global credential, project_client

    if project_client is None:
        validate_foundry_settings()
        endpoint = (PROJECT_ENDPOINT or "").strip()
        if not endpoint:
            raise ValueError("Missing Foundry environment variable: PROJECT_ENDPOINT_STRING")
        active_credential = DefaultAzureCredential()
        credential = active_credential
        project_client = AIProjectClient(
            endpoint=endpoint,
            credential=active_credential,
        )

    return project_client

def extract_ticket_number(value: str) -> str:
    if not value:
        return ""

    text = str(value).strip()

    patterns = [
        r"/browse/([A-Z][A-Z0-9]+-\d+)",
        r"[?&]selectedIssue=([A-Z][A-Z0-9]+-\d+)",
        r"[?&]ticket=([A-Z][A-Z0-9]+-\d+)",
        r"\b([A-Z][A-Z0-9]+-\d+)\b",
    ]

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            return match.group(1).upper()

    return ""


def _configured_jira_origin() -> tuple[str, str]:
    base = (JIRA_BASE_URL or "").strip()
    if not base:
        return "", ""

    parsed = urlparse(
        base if re.match(r"^https?://", base, re.IGNORECASE) else f"https://{base}"
    )
    return (parsed.scheme or "").lower(), (parsed.netloc or "").lower()


def extract_ticket_number_from_jira_link(ticket_link: str) -> str:
    raw = (ticket_link or "").strip()
    if not raw:
        return ""

    parsed = urlparse(raw)

    if parsed.scheme.lower() not in {"http", "https"}:
        return ""

    if not parsed.netloc or parsed.username or parsed.password:
        return ""

    configured_scheme, configured_netloc = _configured_jira_origin()
    if configured_scheme and parsed.scheme.lower() != configured_scheme:
        return ""

    if configured_netloc and parsed.netloc.lower() != configured_netloc:
        return ""

    path_segments = [
        unquote(segment).strip()
        for segment in (parsed.path or "").split("/")
        if segment.strip()
    ]

    for marker in {"browse", "issues"}:
        for index, segment in enumerate(path_segments):
            if segment.lower() == marker and index + 1 < len(path_segments):
                return path_segments[index + 1].upper()

    query = parse_qs(parsed.query or "")
    for param_name in ("selectedIssue", "ticket", "issue", "issueKey"):
        for value in (query.get(param_name) or []):
            ticket_number = extract_ticket_number(value)
            if ticket_number:
                return ticket_number

    if parsed.fragment:
        fragment_ticket = extract_ticket_number_from_jira_link(
            f"{parsed.scheme}://{parsed.netloc}/{parsed.fragment.lstrip('/')}"
        )
        if fragment_ticket:
            return fragment_ticket

    return ""


def is_valid_jira_ticket_link(ticket_link: str) -> bool:
    ticket_number = extract_ticket_number_from_jira_link(ticket_link)
    return bool(ticket_number and is_valid_jira_ticket(ticket_number))


def normalize_ticket_input(ticket_value: str) -> tuple[str, str]:
    raw = (ticket_value or "").strip()
    if not raw:
        return "", ""

    if raw.lower().startswith(("http://", "https://")):
        ticket_number = extract_ticket_number_from_jira_link(raw)
        return ticket_number, raw if ticket_number else ""

    return extract_ticket_number(raw), ""


def is_valid_ticket_or_link(raw_value: str) -> bool:
    return is_valid_jira_ticket_link(raw_value)


def find_agent_reference(agent_name: Optional[str]):
    agent_name = (agent_name or "").strip()
    if not agent_name:
        raise RuntimeError("A Foundry agent name is required.")

    client = get_project_client()
    agents = list(client.agents.list())

    if not agents:
        raise RuntimeError("No agents were found in this Azure AI Foundry project.")

    matches = [a for a in agents if getattr(a, "name", None) == agent_name]

    if not matches:
        available_names = [getattr(a, "name", None) for a in agents]
        raise RuntimeError(
            f"Configured AZURE_AGENT_NAME '{agent_name}' was not found. "
            f"Available agent names: {available_names}"
        )

    agent = None
    for a in matches:
        if getattr(a, "version", None):
            agent = a
            break

    if agent is None:
        agent = matches[0]

    ref = {
        "name": getattr(agent, "name", None),
        "type": "agent_reference",
    }

    agent_version = getattr(agent, "version", None)
    if agent_version:
        ref["version"] = agent_version

    return ref


def normalize_iac_relative_path(filename: str, allow_tfvars: bool = False) -> str:
    raw = (filename or "main.tf").strip().replace("\\", "/")
    raw = raw.lstrip("/")

    parts = []
    for part in raw.split("/"):
        if not part or part == ".":
            continue
        if part == "..":
            raise ValueError("Terraform file paths must be relative and cannot contain '..'.")
        parts.append(part)

    cleaned = "/".join(parts) if parts else "main.tf"

    if allow_tfvars and cleaned.endswith(".tfvars"):
        return cleaned

    if not cleaned.endswith(".tf"):
        cleaned += ".tf"

    return cleaned


def normalize_tf_relative_path(filename: str) -> str:
    return normalize_iac_relative_path(filename, allow_tfvars=False)

def normalize_agent_relative_tf_path(filename: str, cloud: str) -> str:
    raw = (filename or "main.tf").strip().replace("\\", "/").lstrip("/")
    path = normalize_iac_relative_path(raw, allow_tfvars=(cloud == "azure"))

    if cloud == "azure":
        forbidden_prefixes = (
            "changes/",
            "temp/",
            "generated/",
            "scratch/",
            "azure/",
            "azure_module/",
            "tf-azure-hub/",
            "vena_repos/",
            "vena-repos/",
            "terraform/",
        )

        if path.startswith(forbidden_prefixes):
            raise ValueError(
                "Azure filenames must be repo-relative only. "
                "Do not prefix filenames with repo names, terraform/, changes/, or scratch paths."
            )

    if cloud == "aws":
        if path.startswith(("changes/", "temp/", "generated/", "scratch/")):
            raise ValueError("AWS filenames must not use scratch or generated paths.")

    return path


AZURE_MODULE_POPULATION_REQUIRED_FILES = ("main.tf", "variables.tf", "outputs.tf")

AZURE_MODULE_POPULATION_FORBIDDEN_TEXT = (
    "todo",
    "changeme",
    "change me",
    "replace me",
    "replace_me",
    "fill this",
    "fill_this",
    "placeholder",
    "pending design",
    "implementation pending",
    "module implementation pending",
    "not implemented",
    "example only",
    "sample only",
)


def normalize_azure_module_repo_population_path(filename: str) -> str:
    raw = (filename or "main.tf").strip().replace("\\", "/").lstrip("/")

    if not raw:
        raw = "main.tf"

    parts = []
    for part in raw.split("/"):
        if not part or part == ".":
            continue
        if part == "..":
            raise ValueError(
                "Azure module repo population file paths must be relative and cannot contain '..'."
            )
        parts.append(part)

    cleaned = "/".join(parts) if parts else "main.tf"

    forbidden_prefixes = (
        "terraform/",
        "tf-azure-hub/",
        "vena_repos/",
        "vena-repos/",
        "changes/",
        "temp/",
        "generated/",
        "scratch/",
        "azure/",
    )

    if cleaned.startswith(forbidden_prefixes):
        raise ValueError(
            "Azure module repo population files must be relative to the module repository root."
        )

    if "/" in cleaned:
        raise ValueError(
            "Azure module repo population must generate root-level module files only."
        )

    lower = cleaned.lower()

    if lower in {"readme", "readme.md", "readme.md.tf"}:
        return "README.md"

    if lower.endswith(".md"):
        raise ValueError(
            "Only README.md may be generated as a markdown file during azure_module_repo_population."
        )

    if lower in {"main.tf", "variables.tf", "outputs.tf", "versions.tf"}:
        return lower

    if not lower.endswith(".tf"):
        cleaned += ".tf"

    if not re.fullmatch(r"[A-Za-z0-9_.-]+\.tf", cleaned):
        raise ValueError(f"Invalid Azure module repo population filename: {cleaned}")

    return cleaned


def _hcl_without_comments(content: str) -> str:
    text = (content or "").replace("\r\n", "\n")
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.DOTALL)
    lines = []

    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("#") or stripped.startswith("//"):
            continue
        lines.append(line)

    return "\n".join(lines).strip()


def _contains_forbidden_population_text(content: str) -> bool:
    lower = (content or "").lower()
    return any(marker in lower for marker in AZURE_MODULE_POPULATION_FORBIDDEN_TEXT)


def _has_main_tf_implementation_block(content: str) -> bool:
    text = _hcl_without_comments(content)
    return bool(
        re.search(r'(?m)^\s*resource\s+"[^\"]+"\s+"[^\"]+"\s*\{', text)
        or re.search(r'(?m)^\s*data\s+"[^\"]+"\s+"[^\"]+"\s*\{', text)
        or re.search(r'(?m)^\s*module\s+"[^\"]+"\s*\{', text)
    )


def _has_variable_block(content: str) -> bool:
    return bool(re.search(r'(?m)^\s*variable\s+"[A-Za-z0-9_]+"\s*\{', _hcl_without_comments(content)))


def _has_output_block(content: str) -> bool:
    return bool(re.search(r'(?m)^\s*output\s+"[A-Za-z0-9_]+"\s*\{', _hcl_without_comments(content)))


def validate_azure_module_population_core_files(agent_result: dict) -> dict:
    if not isinstance(agent_result, dict):
        return agent_result

    if (agent_result.get("workflow") or "").strip() != "azure_module_repo_population":
        return agent_result

    files = agent_result.get("files") or []
    files_by_name = {}
    normalized_files = []
    seen = set()

    for file_data in files:
        if not isinstance(file_data, dict):
            continue

        filename = normalize_azure_module_repo_population_path(file_data.get("filename") or "")
        content = file_data.get("content", "")
        if not isinstance(content, str):
            content = str(content or "")

        if filename in seen:
            continue

        normalized_content = content.rstrip() + "\n"
        normalized_files.append({
            "filename": filename,
            "content": normalized_content,
        })
        files_by_name[filename] = normalized_content
        seen.add(filename)

    missing = [
        filename
        for filename in AZURE_MODULE_POPULATION_REQUIRED_FILES
        if filename not in files_by_name
    ]

    if missing:
        raise ValueError(
            "azure_module_repo_population must generate real root-level module files: "
            + ", ".join(AZURE_MODULE_POPULATION_REQUIRED_FILES)
            + f". Missing: {', '.join(missing)}"
        )

    for filename in AZURE_MODULE_POPULATION_REQUIRED_FILES:
        content = files_by_name.get(filename) or ""

        if not _hcl_without_comments(content):
            raise ValueError(
                f"{filename} cannot be empty or comment-only. "
                "The Azure module population stage must generate real Terraform code."
            )

        if _contains_forbidden_population_text(content):
            raise ValueError(
                f"{filename} contains placeholder or pending-design text. "
                "The Azure module population stage must generate real Terraform code or ask for clarification."
            )

    if not _has_main_tf_implementation_block(files_by_name["main.tf"]):
        raise ValueError(
            "main.tf must contain at least one real Terraform resource, data, or module block."
        )

    if not _has_variable_block(files_by_name["variables.tf"]):
        raise ValueError(
            "variables.tf must contain at least one real Terraform variable block."
        )

    if not _has_output_block(files_by_name["outputs.tf"]):
        raise ValueError(
            "outputs.tf must contain at least one real Terraform output block."
        )

    normalized_files, variable_issues = normalize_generated_module_variable_files(
        normalized_files,
        "azure_module_repo_population",
        user_prompt=agent_result.get("user_prompt") or agent_result.get("summary") or "",
    )
    if variable_issues:
        raise ModuleVariableValuesRequired(
            normalized_files,
            variable_issues,
            workflow="azure_module_repo_population",
        )

    agent_result["files"] = normalized_files
    return agent_result


def ensure_tf_extension(filename: str) -> str:
    return normalize_tf_relative_path(filename)

def safe_join_under_folder(folder: str, relative_tf_path: str) -> str:
    base = (folder or "").strip().strip("/")
    rel = normalize_iac_relative_path(
        relative_tf_path,
        allow_tfvars=str(relative_tf_path or "").strip().endswith(".tfvars"),
    )

    if rel.startswith("../") or rel == ".." or "/../" in rel:
        raise ValueError("Terraform file path escapes the target folder.")

    # Repo-root mode: valid for tf-azure-hub root and terraform-github/vena_repos root.
    if base in ("", "."):
        return rel

    combined = f"{base}/{rel}".replace("\\", "/")
    combined = re.sub(r"/+", "/", combined)

    if not combined.startswith(base + "/"):
        raise ValueError("Terraform file path escapes the target folder.")

    return combined



def normalize_cloud(cloud: Any | None) -> str:
    cloud = (cloud or "").strip().lower()
    if cloud in ["aws", "amazon", "amazon-web-services"]:
        return "aws"
    if cloud in ["azure", "microsoft-azure"]:
        return "azure"
    raise ValueError("Cloud must be either 'aws' or 'azure'.")

def normalize_repo_target(
    cloud: Any | None,
    repo_target: Any | None = None,
    workflow: Any | None = None,
) -> str:
    cloud = normalize_cloud(cloud)
    repo_target = (repo_target or "").strip().lower().replace("-", "_")
    workflow = (workflow or "").strip()

    if cloud == "aws":
        return "tf-devops"

    if repo_target == "vena_repos":
        return "vena_repos"

    if repo_target in {"tf_azure_hub", "tf-azure-hub"}:
        return "tf-azure-hub"

    if repo_target in {
        AZURE_MODULE_REPO_TARGET,
        AZURE_MODULE_REPO_TARGET.replace("-", "_"),
    }:
        return AZURE_MODULE_REPO_TARGET

    if workflow == "azure_module_repo_creation":
        return "vena_repos"

    if workflow == "azure_module_repo_population":
        return AZURE_MODULE_REPO_TARGET

    return "tf-azure-hub"

def state_bucket_for_target(cloud: Any | None, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    repo_target = normalize_repo_target(cloud, repo_target, workflow)

    if cloud == "aws":
        return "aws"
    if repo_target == "vena_repos":
        return "azure_module"
    if repo_target == AZURE_MODULE_REPO_TARGET:
        return "azure_module_population"
    return "azure_consumer"

def github_repo_for_cloud(cloud: Any | None, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    repo_target = normalize_repo_target(cloud, repo_target, workflow)

    if cloud == "aws":
        return _require_setting(GITHUB_AWS_REPO, "GITHUB_AWS_REPO")
    if repo_target == "vena_repos":
        return _require_setting(GITHUB_VENA_REPO, "GITHUB_VENA_REPO")
    if repo_target == AZURE_MODULE_REPO_TARGET:
        raise RuntimeError(
            "azure_module_repo_population requires a dynamic module repo target. "
            "Use commit_azure_module_repo_population_files instead of github_repo_for_cloud."
        )
    return _require_setting(GITHUB_AZURE_REPO, "GITHUB_AZURE_REPO")


def github_base_branch_for_cloud(cloud: Any | None, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    repo_target = normalize_repo_target(cloud, repo_target, workflow)

    if cloud == "aws":
        return GITHUB_AWS_BASE_BRANCH
    if repo_target == "vena_repos":
        return GITHUB_VENA_BASE_BRANCH
    if repo_target == AZURE_MODULE_REPO_TARGET:
        return GITHUB_AZURE_BASE_BRANCH
    return GITHUB_AZURE_BASE_BRANCH


def github_pr_source_branch_for_cloud(cloud: Any | None, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    repo_target = normalize_repo_target(cloud, repo_target, workflow)

    if cloud == "aws":
        return GITHUB_PR_SOURCE_BRANCH_AWS
    if repo_target == "vena_repos":
        return GITHUB_PR_SOURCE_BRANCH_VENA
    return GITHUB_PR_SOURCE_BRANCH_AZURE


def github_branch_seed_for_cloud(cloud: Any | None, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    seed = (github_pr_source_branch_for_cloud(cloud, repo_target=repo_target, workflow=workflow) or "").strip()
    if seed:
        return seed
    return github_base_branch_for_cloud(cloud, repo_target=repo_target, workflow=workflow)

def safe_normalize_cloud(cloud: Any | None):
    try:
        return normalize_cloud(str(cloud or ""))
    except Exception:
        return None


# Teams environment-to-repository routing hints. Explicit cloud/provider terms
# always win. These mappings are used only when the prompt does not identify a
# cloud clearly, so environment names can select the correct live GitHub repo.
TEAMS_AWS_ENVIRONMENT_HINTS = {
    "ca3", "ca3_dr", "devops", "eu1", "eu1_dr", "eu2", "eu2_dr",
    "global", "observe", "sqlstaging", "sqlstaging_ca", "sqlstaging_eu",
    "sqlstaging_eu2", "sqlstaging_us4", "sqlstaging_west", "us1", "us1_dr",
    "us2", "us2_dr", "us3", "us3_dr", "us4", "us4_dr", "bolt", "bolt_dr",
    "bolt_sqlstaging", "dev", "dev_devops", "dev_sqlstaging", "minidev",
    "minidev_sqlstaging",
}
TEAMS_AZURE_ENVIRONMENT_HINTS = {
    "npr-int", "npr-stg", "sbx-infra", "ca4", "eu3", "us5", "us6",
    "prd-ca4", "prd-eu3", "prd-us5", "prd-us6",
}


def _prompt_environment_tokens(prompt: str) -> set[str]:
    normalized = str(prompt or "").lower().replace("_", "-")
    return {
        token.strip("-")
        for token in re.findall(r"[a-z0-9]+(?:-[a-z0-9]+)*", normalized)
        if token.strip("-")
    }


def infer_cloud_from_environment(prompt: str):
    """Infer cloud from a uniquely mapped environment when cloud is omitted."""
    tokens = _prompt_environment_tokens(prompt)
    aws_matches = sorted(tokens & TEAMS_AWS_ENVIRONMENT_HINTS)
    azure_matches = sorted(tokens & TEAMS_AZURE_ENVIRONMENT_HINTS)

    if aws_matches and not azure_matches:
        return "aws"
    if azure_matches and not aws_matches:
        return "azure"
    return None


def infer_cloud_from_prompt(prompt: str):
    """Infer cloud from explicit provider/resource wording, then environment."""
    text = normalize_yes_no_reply(prompt)
    if not text:
        return None

    azure_markers = [
        "azure",
        "azurerm",
        "resource group",
        "vnet",
        "virtual network",
        "azure vm",
        "azure linux vm",
        "azure windows vm",
        "azure container app",
        "azure container apps",
        "container app",
        "container apps",
        "aca app",
        " aca ",
    ]
    aws_markers = [
        "aws",
        "amazon web services",
        "ec2",
        "s3",
        "rds",
        "iam",
        "vpc",
        "eks",
        "lambda",
        "redshift",
        "dynamodb",
        "cloudfront",
        "sqs",
        "sns",
        "elasticache",
    ]

    has_azure = any(marker in text for marker in azure_markers)
    has_aws = any(marker in text for marker in aws_markers)

    if has_azure and not has_aws:
        return "azure"
    if has_aws and not has_azure:
        return "aws"
    if has_azure and has_aws:
        return None

    return infer_cloud_from_environment(prompt)

def get_approved_azure_consumer_repos() -> list[str]:
    raw = (GITHUB_AZURE_APPROVED_CONSUMER_REPOS or "").strip()
    repos = []

    if raw:
        for item in raw.split(","):
            name = (item or "").strip()
            if name:
                repos.append(name)

    if GITHUB_AZURE_REPO and GITHUB_AZURE_REPO not in repos:
        repos.insert(0, GITHUB_AZURE_REPO)

    # preserve order
    seen = set()
    result = []
    for repo in repos:
        if repo not in seen:
            seen.add(repo)
            result.append(repo)

    return result




import re





def generate_short_ticket_title(text: str) -> str:
    if not text:
        return "New Request"

    cleaned = re.sub(r"\s+", " ", text).strip()
    cleaned = re.sub(r"[^\w\s-]", "", cleaned)

    if not cleaned:
        return "New Request"

    words = cleaned.split()[:5]
    return " ".join(word.capitalize() for word in words)
PENDING_CLOUD_CLARIFICATIONS = {}


def store_pending_cloud_clarification(
    thread_id: str,
    ticket_number: str,
    original_prompt: str,
    requested_mode: str = "",
    requested_cloud: str = "",
    ticket_link: str = "",
    ticket_title: str = "",
):
    key = hashlib.sha1(
        f"{thread_id or 'no-thread'}::{ticket_number or ''}::{original_prompt}".encode("utf-8")
    ).hexdigest()

    PENDING_CLOUD_CLARIFICATIONS[key] = {
        "thread_id": thread_id,
        "ticket_number": (ticket_number or "").strip().upper(),
        "original_prompt": original_prompt,
        "requested_mode": requested_mode or "",
        "requested_cloud": requested_cloud or "",
        "ticket_link": ticket_link or "",
        "ticket_title": ticket_title or "",
    }
    return key


def get_pending_cloud_clarification(thread_id: str, ticket_number: str):
    thread_id = str(thread_id or "")
    ticket_number = (ticket_number or "").strip().upper()

    for _, item in PENDING_CLOUD_CLARIFICATIONS.items():
        if str(item.get("thread_id") or "") == thread_id and (item.get("ticket_number") or "") == ticket_number:
            return item
    return None


def clear_pending_cloud_clarification(thread_id: str, ticket_number: str):
    thread_id = str(thread_id or "")
    ticket_number = (ticket_number or "").strip().upper()

    keys_to_delete = []
    for key, item in PENDING_CLOUD_CLARIFICATIONS.items():
        if str(item.get("thread_id") or "") == thread_id and (item.get("ticket_number") or "") == ticket_number:
            keys_to_delete.append(key)

    for key in keys_to_delete:
        PENDING_CLOUD_CLARIFICATIONS.pop(key, None)

def build_thread_label(ticket_title: str, ticket_number: str) -> str:
    title = (ticket_title or "New Request").strip()
    number = (ticket_number or "UNASSIGNED").strip()
    return f"{title} - {number}"


def build_enhanced_conversation_label(ticket_number: str, ticket_title: str, conversation_id: str | None) -> str:
    title = (ticket_title or "").strip()
    ticket = (ticket_number or "").strip()

    if title and ticket:
        return f"{title} - {ticket}"

    if ticket:
        return build_conversation_label(ticket, conversation_id)

    return title or (conversation_id or "New")


def build_pr_body(
    user_prompt: str,
    ticket_link: str = "",
    ticket_number: str = "",
    ticket_title: str = "",
    cloud: Optional[str] = "",
    folder: Optional[str] = "",
    thread_id: Optional[str] = "",
    branch_cycle=None,
    files=None,
    summary: str = "",
) -> str:
    files = files or []

    ticket_header = build_thread_label(ticket_title, ticket_number)

    parts = []

    if summary:
        parts.append(summary)
        parts.append("")

    parts.append("## Ticket")
    parts.append(ticket_header)

    if ticket_link:
        parts.append("")
        parts.append("## Ticket Link")
        parts.append(ticket_link)

    parts.append("")
    parts.append("## Metadata")
    parts.append(f"- Cloud: {cloud or 'Not provided'}")
    parts.append(f"- Folder: {folder or 'Not provided'}")
    parts.append(f"- Thread ID: {thread_id or 'Not provided'}")

    if branch_cycle is not None:
        parts.append(f"- Branch Cycle: {branch_cycle}")

    if files:
        parts.append("")
        parts.append("## Files Updated")
        for file_path in files:
            parts.append(f"- {file_path}")

    parts.append("")
    parts.append("## Request")
    parts.append(user_prompt)

    parts.append("")
    parts.append("## Automation")
    parts.append("PR raised using Terrabot AI.")

    return "\n".join(parts)



def extract_first_balanced_json_object(text: str) -> str:
    text = (text or "").strip()
    if not text:
        raise ValueError("Could not parse JSON from agent response.")

    start = text.find("{")
    if start == -1:
        raise ValueError("Could not parse JSON from agent response.")

    depth = 0
    in_string = False
    escape = False

    for i in range(start, len(text)):
        ch = text[i]

        if in_string:
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return text[start:i + 1]

    raise ValueError("Could not parse JSON from agent response.")


def extract_json_from_text(text: str) -> dict:
    text = (text or "").strip()

    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass

    fenced = re.search(r"```json\s*(\{.*?\})\s*```", text, re.DOTALL | re.IGNORECASE)
    if fenced:
        try:
            return json.loads(fenced.group(1))
        except json.JSONDecodeError:
            pass

    candidate = extract_first_balanced_json_object(text)
    return json.loads(candidate)


def looks_like_infra_payload(text: str) -> bool:
    text = (text or "").strip().lower()
    infra_markers = [
        '"mode"', '"infra"', '"cloud"', '"files"', '"filename"', '"content"',
        "```json", "{", "terraform", ".tf"
    ]
    marker_hits = sum(1 for marker in infra_markers if marker in text)
    return marker_hits >= 4 and ('"files"' in text or '"content"' in text)


def extract_possible_json_object(text: str) -> str:
    text = (text or "").strip()
    if not text:
        return ""

    fenced = re.search(r"```json\s*(\{.*?\})\s*```", text, re.DOTALL | re.IGNORECASE)
    if fenced:
        return fenced.group(1).strip()

    start = text.find("{")
    end = text.rfind("}")
    if start != -1 and end != -1 and end > start:
        return text[start:end + 1].strip()

    return ""


def agent_reply_looks_like_infra_json(text: str) -> bool:
    candidate = extract_possible_json_object(text).lower()
    if not candidate:
        return False

    required_markers = ['"cloud"', '"files"', '"filename"', '"content"']
    return all(marker in candidate for marker in required_markers)

def _try_parse_agent_output_base(agent_text: str):
    candidate = extract_possible_json_object(agent_text) or (agent_text or "").strip()
    return parse_agent_output(candidate)

def _repair_and_parse_agent_output_base(
    conversation_id: str,
    original_agent_input: str,
    bad_agent_reply: str,
    parse_error: Exception,
):
    del conversation_id

    repair_prompt = {
        "task": "Return corrected Terraform infra JSON only.",
        "error": str(parse_error),
        "original_agent_input": original_agent_input,
        "bad_agent_reply": bad_agent_reply,
        "absolute_rules": [
            "Return valid JSON only.",
            "Do not include markdown.",
            "Do not explain.",
            "Use repo_target='vena_repos', never 'vena-repos'.",
            "If workflow is azure_module_repo_creation, create ONLY the terraform-github/vena_repos module repository definition.",
            "For azure_module_repo_creation, return exactly one root-level .tf file that defines the requested repository.",
            "For azure_module_repo_creation, the GitHub repo name may be any valid repo name supplied by the user; do not force a tf-module or tf_module prefix.",
            "For azure_module_repo_creation, content must use module source '../modules/repo'.",
            "For azure_module_repo_creation, merge_commit_title must be exactly one of: PR_TITLE, MERGE_MESSAGE. Use PR_TITLE by default.",
            "For azure_module_repo_creation, merge_commit_message must be exactly one of: PR_BODY, PR_TITLE, BLANK. Use PR_BODY by default. BLANK is a GitHub enum value here, not a placeholder.",
            "For azure_module_repo_creation, never use resource 'github_repository'.",
            "For azure_module_repo_creation, never create azurerm resources, variables, outputs, provider blocks, main.tf, variables.tf, outputs.tf, versions.tf, README, folders, changes/, tf-azure-hub/, terraform/, or azure/ paths.",
        ],
        "required_shape": {
            "mode": "infra",
            "cloud": "azure",
            "workflow": "azure_module_repo_creation",
            "repo_target": "vena_repos",
            "title": "[AZURE] Create Azure module repository",
            "summary": "Creates the Azure module repository definition in terraform-github/vena_repos.",
            "files": [
                {
                    "filename": "azure_linux_vm_module.tf",
                    "content": "module \"azure_linux_vm_module\" {\n  source = \"../modules/repo\"\n\n  name                   = \"azure-linux-vm-module\"\n  description            = \"Repository for Azure Linux VM Module\"\n  delete_branch_on_merge = true\n  has_issues             = true\n  default_branch         = \"main\"\n  merge_commit_title     = \"PR_TITLE\"\n  merge_commit_message   = \"PR_BODY\"\n  actions_enabled        = false\n\n  managed_files = {\n    PULL_REQUEST_TEMPLATE = {\n      repo_path  = \".github/PULL_REQUEST_TEMPLATE.md\"\n      local_file = \"devops.md\"\n    }\n    CODEOWNERS = {\n      repo_path     = \".github/CODEOWNERS\"\n      file_contents = \"* @venasolutions/${var.vena_teams.sto.slug}\"\n    }\n    PRE_COMMIT = {\n      repo_path  = \".pre-commit-config.yaml\"\n      local_file = \"terraform.yml\"\n    }\n  }\n\n  collaborators = {}\n\n  managed_branches = [\"main\"]\n}\n"
                }
            ]
        }
    }

    _new_conversation_id, repaired_reply = call_agent(
        None,
        json.dumps(repair_prompt, indent=2),
    )

    return try_parse_agent_output(repaired_reply), repaired_reply


def is_valid_github_repo_name(repo_name: str) -> bool:
    repo_name = (repo_name or "").strip()
    if not repo_name or repo_name in {".", ".."}:
        return False
    if repo_name.endswith(".git") or "/" in repo_name or "\\" in repo_name:
        return False
    return bool(re.fullmatch(r"[A-Za-z0-9_.-]+", repo_name))


def sanitize_azure_module_repo_name(repo_name: str) -> str:
    """Return a safe GitHub repo name while preserving hyphen normalization."""
    value = (repo_name or "").strip().strip("`'\"<>()[]{}")
    if not value:
        return ""

    value = value.replace("https://github.com/", "").replace("git@github.com:", "")
    value = value.split("?", 1)[0].split("#", 1)[0].strip("/")

    if "/" in value:
        value = value.rsplit("/", 1)[-1]

    value = re.sub(r"\.git$", "", value, flags=re.IGNORECASE)
    value = re.sub(r"[\s_]+", "-", value.lower())
    value = re.sub(r"[^a-z0-9.-]", "-", value)
    value = re.sub(r"-+", "-", value).strip(".-")

    if not is_valid_github_repo_name(value):
        return ""

    return value[:100]


def terraform_label_from_repo_name(repo_name: str, fallback: str = "azure_module") -> str:
    label = (repo_name or fallback or "azure_module").strip().lower()
    label = re.sub(r"[^a-z0-9_]+", "_", label.replace("-", "_").replace(".", "_"))
    label = re.sub(r"_+", "_", label).strip("_")

    if not label:
        label = fallback or "azure_module"
    if not re.match(r"^[a-z_]", label):
        label = f"repo_{label}"

    return label[:100]


def _candidate_azure_repo_name_from_text(value: str) -> str:
    candidate = (value or "").strip().strip("`'\"")
    if not candidate:
        return ""

    candidate = re.split(
        r"(?:\s+for\s+)|(?:\s+please\b)|(?:\s+and\b)|(?:\s+then\b)|[,;\n]",
        candidate,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip().strip("`'\".:)")
    candidate = re.sub(r"\s+", " ", candidate).strip()

    if re.match(r"^(?:for|first)\b", candidate, re.IGNORECASE):
        return ""

    stop_values = {
        "a", "an", "the", "first", "new", "module", "repo", "repository",
        "azure", "terraform", "please", "one", "it", "this", "that",
        "custom", "name", "new repo", "new repository", "module repo",
        "module repository", "azure module", "azure repo", "azure repository",
        "yes", "y", "no", "n", "create", "make", "build", "for",
        "named", "called", "as",
    }
    if not candidate or candidate.lower() in stop_values:
        return ""

    return sanitize_azure_module_repo_name(candidate)


def extract_requested_azure_module_repo_name(prompt: str) -> str:
    """Extract an explicit custom Azure module repo name from user text, if provided."""
    text = re.sub(r"\s+", " ", (prompt or "").strip())
    if not text:
        return ""

    patterns = [
        r"\b(?:target_)?(?:module_)?repo(?:sitory)?[_ -]?name\s*(?:is|=|:)?\s*[`'\"]?([A-Za-z0-9][A-Za-z0-9_. \-]{1,120})",
        r"\b(?:repo|repository)\s+(?:named|called)\s+[`'\"]?([A-Za-z0-9][A-Za-z0-9_. \-]{1,120})",
        r"\b(?:named|called|call\s+it|name\s+it)\s+[`'\"]?([A-Za-z0-9][A-Za-z0-9_. \-]{1,120})",
        r"\b(?:create|make|build)\s+(?:a\s+|an\s+|the\s+)?(?:new\s+)?(?:azure\s+)?(?:module\s+)?(?:repo|repository)\s+(?!for\b|first\b)(?:named\s+|called\s+|as\s+)?[`'\"]?([A-Za-z0-9][A-Za-z0-9_. \-]{1,120})",
        r"\buse\s+(?:repo|repository)\s+[`'\"]?([A-Za-z0-9][A-Za-z0-9_. \-]{1,120})",
    ]

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if not match:
            continue

        candidate = _candidate_azure_repo_name_from_text(match.group(1))
        if candidate:
            return candidate

    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{1,120}", text):
        return _candidate_azure_repo_name_from_text(text)

    return ""


def build_azure_module_creation_prompt_with_repo_name(original_prompt: str, repo_name_source: str = "") -> str:
    repo_name = (
        extract_requested_azure_module_repo_name(repo_name_source)
        or extract_requested_azure_module_repo_name(original_prompt)
    )
    original_prompt = (original_prompt or "").strip()
    if not repo_name:
        return original_prompt
    if repo_name in original_prompt.lower():
        return original_prompt
    return f"{original_prompt}\n\nRequested Azure module repo name: {repo_name}"


def extract_azure_module_repo_name_from_confirmation_reply(reply: str) -> str:
    repo_name = extract_requested_azure_module_repo_name(reply)
    if repo_name:
        return repo_name

    cleaned = (reply or "").strip().strip("`'\"")
    normalized = normalize_yes_no_reply(cleaned)
    if normalized in AFFIRMATIVE_REPLIES or normalized in NEGATIVE_REPLIES:
        return ""
    if re.search(r"\s", cleaned):
        return ""
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{1,99}", cleaned):
        return ""

    return sanitize_azure_module_repo_name(cleaned)


def _extract_hcl_string_assignment(tf_content: str, key: str) -> str:
    match = re.search(
        rf'^\s*{re.escape(key)}\s*=\s*"([^"]*)"',
        tf_content or "",
        re.MULTILINE,
    )
    return match.group(1).strip() if match else ""


def _validate_azure_repo_merge_commit_settings(tf_content: str) -> None:
    merge_commit_title = _extract_hcl_string_assignment(tf_content, "merge_commit_title")
    merge_commit_message = _extract_hcl_string_assignment(tf_content, "merge_commit_message")

    if merge_commit_title not in ALLOWED_GITHUB_MERGE_COMMIT_TITLES:
        allowed = ", ".join(sorted(ALLOWED_GITHUB_MERGE_COMMIT_TITLES))
        raise ValueError(
            "azure_module_repo_creation must set merge_commit_title to one of: "
            f"{allowed}."
        )

    if merge_commit_message not in ALLOWED_GITHUB_MERGE_COMMIT_MESSAGES:
        allowed = ", ".join(sorted(ALLOWED_GITHUB_MERGE_COMMIT_MESSAGES))
        raise ValueError(
            "azure_module_repo_creation must set merge_commit_message to one of: "
            f"{allowed}."
        )


def infer_azure_module_resource_slug(original_prompt: str) -> str:
    text = (original_prompt or "").strip().lower()
    explicit = re.search(r"(?:module|repo|repository)\s+(?:for\s+)?([a-z0-9][a-z0-9 _-]{1,80})", text)
    if explicit:
        text = explicit.group(1)

    replacements = {
        "virtual machine": "vm",
        "linux virtual machine": "linux vm",
        "windows virtual machine": "windows vm",
    }
    for old, new_value in replacements.items():
        text = text.replace(old, new_value)

    tokens = re.findall(r"[a-z0-9]+", text)
    stop_words = {
        "azure", "terraform", "module", "repo", "repository", "resource",
        "create", "creating", "new", "update", "for", "with", "and",
        "the", "a", "an", "to", "of", "in", "on", "using", "use",
        "need", "please", "from", "into", "this", "that", "it", "first",
        "empty", "github", "definition", "pr", "allow", "allows", "name",
        "named", "called", "as", "requested",
    }
    resource_tokens = [token for token in tokens if token not in stop_words]

    if not resource_tokens:
        resource_tokens = ["module"]

    slug = "-".join(resource_tokens[:6])
    slug = re.sub(r"[^a-z0-9-]", "-", slug).strip("-")
    slug = re.sub(r"-+", "-", slug)
    return slug or "module"


def generate_azure_module_repo_creation_with_agent(
    conversation_id: str,
    original_prompt: str,
    requested_repo_name: str = "",
) -> dict:
    """Generate Azure module-repository Terraform exclusively through Foundry.

    The backend supplies the resolved user request and repository evidence; it
    never constructs Terraform/HCL itself. Any requested repository name is
    passed to Foundry as user intent, not converted into backend-owned code.
    """
    request = {
        "task": "Generate the requested Azure module repository Terraform using the live repository evidence and Terrabot Foundry instructions.",
        "user_request": str(original_prompt or "").strip(),
        "requested_repo_name": sanitize_azure_module_repo_name(requested_repo_name)
        or extract_requested_azure_module_repo_name(original_prompt),
        "backend_role": "evidence_and_transport_only",
        "rules": [
            "Infer the repository workflow and Terraform structure from supplied live repository evidence.",
            "Generate all Terraform/HCL in Foundry; the backend must not synthesize Terraform.",
            "Return the normal Terrabot infrastructure JSON payload.",
        ],
    }
    _conversation_id, agent_reply = call_agent(
        conversation_id or None,
        json.dumps(request, ensure_ascii=False),
    )
    if not str(agent_reply or "").strip():
        raise RuntimeError("No response returned from Foundry for Azure module repository generation.")
    return try_parse_agent_output(agent_reply)

def cloud_root_dir(cloud: Any | None, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    repo_target = normalize_repo_target(cloud, repo_target, workflow)

    if cloud == "aws":
        root = GITHUB_AWS_DIR
    elif repo_target == "vena_repos":
        root = GITHUB_VENA_DIR
    else:
        root = GITHUB_AZURE_DIR

    return (root or ".").strip().strip("/")


def stable_thread_key(thread_id: str) -> str:
    raw = (thread_id or "default-thread").strip()
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:12]


def build_stable_folder(thread_id: str, cloud: str, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    repo_target = normalize_repo_target(cloud, repo_target, workflow)
    root = cloud_root_dir(cloud, repo_target=repo_target, workflow=workflow)

    # Azure repo-definition PRs must write directly into terraform-github/vena_repos.
    if cloud == "azure" and repo_target == "vena_repos":
        return root or "."

    # Azure consumer PRs must write directly into tf-azure-hub root or configured root.
    if cloud == "azure" and repo_target == "tf-azure-hub":
        return root or "."

    bucket = state_bucket_for_target(cloud, repo_target=repo_target, workflow=workflow)
    suffix = f"changes/{stable_thread_key(thread_id)}/{bucket}"
    return suffix if root in ("", ".") else f"{root}/{suffix}"


def build_branch_prefix(thread_id: str, cloud: str, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    cloud = normalize_cloud(cloud)
    bucket = state_bucket_for_target(cloud, repo_target=repo_target, workflow=workflow)
    base_prefix = github_pr_source_branch_for_cloud(cloud, repo_target=repo_target, workflow=workflow).strip()
    thread_suffix = stable_thread_key(thread_id)
    return f"{base_prefix}-{bucket}-{thread_suffix}"


def build_branch_name(thread_id: str, cloud: str, cycle: int, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> str:
    prefix = build_branch_prefix(thread_id, cloud, repo_target=repo_target, workflow=workflow)
    cycle = max(1, int(cycle or 1))
    return prefix if cycle == 1 else f"{prefix}-v{cycle}"


def parse_branch_cycle(branch_name: str, prefix: str) -> int:
    branch_name = (branch_name or "").strip()
    prefix = (prefix or "").strip()

    if branch_name == prefix:
        return 1

    match = re.fullmatch(rf"{re.escape(prefix)}-v(\d+)", branch_name)
    if match:
        return int(match.group(1))

    return 0



def _require_github_token() -> str:
    token = (GITHUB_TOKEN or os.getenv("TERRABOT_GITHUB_TOKEN") or os.getenv("GH_TOKEN") or "").strip()
    if not token:
        raise RuntimeError(
            "GitHub authentication is not configured in the Function App. "
            "Set GITHUB_TOKEN as an Azure Key Vault-backed application setting."
        )
    return token


def _validate_workspace_repo(owner: str, repo: str) -> tuple[str, str]:
    owner = (owner or "").strip()
    repo = (repo or "").strip().removesuffix(".git")
    if not owner or not repo or not re.fullmatch(r"[A-Za-z0-9_.-]+", owner) or not re.fullmatch(r"[A-Za-z0-9_.-]+", repo):
        raise ValueError("A valid GitHub owner and repository are required.")

    configured_owner = (GITHUB_OWNER or "").strip()
    allowed_repos = {
        value.strip()
        for value in (GITHUB_AWS_REPO, GITHUB_AZURE_REPO, GITHUB_VENA_REPO)
        if value and value.strip()
    }
    allowed_repos.update(
        value.strip()
        for value in (GITHUB_AZURE_APPROVED_CONSUMER_REPOS or "").split(",")
        if value.strip()
    )
    if configured_owner and owner.lower() != configured_owner.lower():
        raise PermissionError(f"Repository owner '{owner}' is not allowed.")
    if allowed_repos and repo not in allowed_repos:
        raise PermissionError(f"Repository '{repo}' is not configured for Terrabot.")
    return owner, repo


def _github_request_error(response: requests.Response, operation: str) -> RuntimeError:
    try:
        payload = response.json()
        message = payload.get("message") or response.text
        documentation_url = payload.get("documentation_url") or ""
    except Exception:
        message = response.text or response.reason
        documentation_url = ""
    suffix = f" Documentation: {documentation_url}" if documentation_url else ""
    return RuntimeError(f"{operation} failed: GitHub returned HTTP {response.status_code}: {message}.{suffix}")


def handle_workspace_branch_request(data: dict) -> dict:
    _require_github_token()
    owner, repo = _validate_workspace_repo(str(data.get("owner") or ""), str(data.get("repo") or ""))
    base = str(data.get("base") or "main").strip()
    branch = str(data.get("branch") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9._/-]+", base) or not re.fullmatch(r"[A-Za-z0-9._/-]+", branch):
        raise ValueError("Branch names may contain only letters, numbers, '.', '_', '/', and '-'.")
    if branch in {base, "main", "master"}:
        raise ValueError("The new branch must be different from the base branch.")

    headers = github_headers()
    base_response = requests.get(
        f"{GITHUB_API}/repos/{owner}/{repo}/git/ref/heads/{base}",
        headers=headers, timeout=30,
    )
    if not base_response.ok:
        raise _github_request_error(base_response, "Reading the base branch")
    base_sha = base_response.json()["object"]["sha"]

    create_response = requests.post(
        f"{GITHUB_API}/repos/{owner}/{repo}/git/refs",
        headers=headers, json={"ref": f"refs/heads/{branch}", "sha": base_sha}, timeout=30,
    )
    if create_response.status_code not in {201, 422}:
        raise _github_request_error(create_response, "Creating the GitHub branch")
    if create_response.status_code == 422:
        exists_response = requests.get(
            f"{GITHUB_API}/repos/{owner}/{repo}/git/ref/heads/{branch}",
            headers=headers, timeout=30,
        )
        if not exists_response.ok:
            raise _github_request_error(create_response, "Creating the GitHub branch")

    return {
        "ok": True,
        "branch": branch,
        "base": base,
        "branch_url": f"https://github.com/{owner}/{repo}/tree/{branch}",
        "compare_url": f"https://github.com/{owner}/{repo}/compare/{base}...{branch}",
        "reply": f"GitHub branch '{branch}' is ready.",
    }


def _github_pull_request_template(owner: str, repo: str, base: str, headers: dict) -> str:
    candidates = (
        ".github/PULL_REQUEST_TEMPLATE.md",
        ".github/pull_request_template.md",
        "PULL_REQUEST_TEMPLATE.md",
        "pull_request_template.md",
        "docs/PULL_REQUEST_TEMPLATE.md",
        "docs/pull_request_template.md",
    )
    for template_path in candidates:
        response = requests.get(
            f"{GITHUB_API}/repos/{owner}/{repo}/contents/{template_path}",
            headers=headers,
            params={"ref": base},
            timeout=30,
        )
        if response.status_code == 404:
            continue
        if not response.ok:
            raise _github_request_error(response, "Reading the pull request template")
        payload = response.json() or {}
        encoded = str(payload.get("content") or "").replace("\n", "")
        if encoded:
            try:
                return base64.b64decode(encoded).decode("utf-8").strip()
            except (ValueError, UnicodeDecodeError) as exc:
                raise RuntimeError(f"Reading the pull request template failed: {exc}") from exc
    return ""


def _github_workspace_compare(owner: str, repo: str, base: str, head: str, headers: dict) -> dict:
    response = requests.get(
        f"{GITHUB_API}/repos/{owner}/{repo}/compare/{base}...{head}",
        headers=headers,
        timeout=30,
    )
    if not response.ok:
        raise _github_request_error(response, "Reading the pull request branch diff")

    payload = response.json() or {}
    files = []
    for item in payload.get("files") or []:
        if not isinstance(item, dict):
            continue
        files.append({
            "filename": item.get("filename") or "",
            "status": item.get("status") or "modified",
            "additions": int(item.get("additions") or 0),
            "deletions": int(item.get("deletions") or 0),
            "changes": int(item.get("changes") or 0),
            "patch": str(item.get("patch") or "")[:12000],
        })

    commits = []
    for item in payload.get("commits") or []:
        commit = (item or {}).get("commit") or {}
        message = str(commit.get("message") or "").strip()
        if message:
            commits.append(message.splitlines()[0][:240])

    return {
        "status": payload.get("status") or "",
        "ahead_by": int(payload.get("ahead_by") or 0),
        "behind_by": int(payload.get("behind_by") or 0),
        "total_commits": int(payload.get("total_commits") or len(commits)),
        "commits": commits[:50],
        "files": files,
    }


def _workspace_pr_changed_file_lines(compare: dict) -> list[str]:
    return [
        f"- `{item.get('filename')}` ({item.get('status')}, +{item.get('additions', 0)}/-{item.get('deletions', 0)})"
        for item in (compare.get("files") or [])
        if item.get("filename")
    ]


def _workspace_pr_template_headings(template: str) -> list[str]:
    return [
        match.group(0).strip()
        for match in re.finditer(r"(?m)^#{1,6}\s+.+$", template or "")
    ]


def _workspace_pr_body_follows_template(template: str, body: str) -> bool:
    """Require every repository-template heading in the same order.

    The Foundry agent may fill section content, but it may not replace the
    repository template with a free-form PR description. This is the guard that
    prevents the compact PR #738-style body when the workspace contains a
    pull_request_template.md like PR #735.
    """
    headings = _workspace_pr_template_headings(template)
    if not headings:
        return bool((body or "").strip())

    cursor = 0
    for heading in headings:
        index = (body or "").find(heading, cursor)
        if index < 0:
            return False
        cursor = index + len(heading)
    return True


def _workspace_pr_section_content(heading: str, compare: dict, prompt: str) -> str:
    heading_text = re.sub(r"^#{1,6}\s+", "", heading or "").strip().lower()
    files = compare.get("files") or []
    changed_lines = _workspace_pr_changed_file_lines(compare)
    details = "\n".join(changed_lines) if changed_lines else "- No changed-file metadata was returned by GitHub."
    request = prompt or "Requested repository changes."

    if any(token in heading_text for token in ("description", "summary", "overview")):
        return (
            f"This pull request applies the requested change from the current branch. "
            f"It updates {len(files)} repository file(s) compared with the base branch."
        )
    if any(token in heading_text for token in ("change", "modified", "files")):
        return details
    if any(token in heading_text for token in ("why", "reason", "required", "motivation")):
        return request
    if any(token in heading_text for token in ("test", "validation", "verify")):
        return "- Run the repository validation and CI checks applicable to the changed files."
    if any(token in heading_text for token in ("deploy", "rollout", "release")):
        return "- Merge through the repository's normal review and deployment workflow."
    if any(token in heading_text for token in ("risk", "impact")):
        return "Review the current branch diff and repository CI results before merge."
    if any(token in heading_text for token in ("ticket", "issue", "reference")):
        return "Not applicable."
    if any(token in heading_text for token in ("checklist", "check list")):
        return "- [ ] Repository validation and CI checks have completed successfully."
    return "Not applicable."


def _workspace_pr_fill_template_fallback(template: str, compare: dict, prompt: str) -> str:
    """Fill the repository template without returning a blank template.

    This is used only when the Foundry metadata call and its repair call fail.
    Headings and checklist labels remain in repository order, while empty or
    instructional section bodies are replaced with grounded compare metadata.
    """
    template = (template or "").strip()
    headings = _workspace_pr_template_headings(template)
    if not template or not headings:
        changed_lines = _workspace_pr_changed_file_lines(compare)
        files = compare.get("files") or []
        description = (
            f"This pull request contains {len(files)} changed file(s) from the current branch compared with the base branch."
            if files else
            "This pull request contains the changes currently present on the source branch."
        )
        details = "\n".join(changed_lines) if changed_lines else "- No changed-file metadata was returned by GitHub."
        return (
            f"## Description\n\n{description}\n\n"
            f"## Changes\n\n{details}\n\n"
            f"## Why was this required?\n\n{prompt or 'Requested repository changes.'}\n\n"
            "## How to test?\n\n- Run the repository validation and CI checks applicable to the changed files.\n\n"
            "## Deployment plan\n\n- Merge through the repository's normal review and deployment workflow."
        )

    matches = list(re.finditer(r"(?m)^#{1,6}\s+.+$", template))
    output: list[str] = []
    preamble = template[:matches[0].start()].strip()
    if preamble:
        output.append(preamble)

    for index, match in enumerate(matches):
        heading = match.group(0).strip()
        section_end = matches[index + 1].start() if index + 1 < len(matches) else len(template)
        original_body = template[match.end():section_end].strip()
        preserved_checklist = [
            line.rstrip()
            for line in original_body.splitlines()
            if re.match(r"^\s*[-*]\s+\[[ xX]\]\s+", line)
        ]
        output.append(heading)
        output.append("")
        output.append(_workspace_pr_section_content(heading, compare, prompt))
        if preserved_checklist:
            output.append("")
            output.extend(preserved_checklist)
        output.append("")

    return "\n".join(output).strip()


def _workspace_pr_fallback_body(template: str, compare: dict, prompt: str) -> str:
    return _workspace_pr_fill_template_fallback(template, compare, prompt)


def _generate_workspace_pr_metadata(
    data: dict,
    owner: Optional[str],
    repo: Optional[str],
    base: str,
    head: str,
    headers: dict | None = None,
    compare_override: dict | None = None,
) -> tuple[str, str, dict]:
    owner = _require_setting(owner, "GITHUB_OWNER")
    repo = _require_setting(repo, "GitHub repository")
    template = str(data.get("template") or "").strip()
    if not template and headers:
        template = _github_pull_request_template(owner, repo, base, headers)

    compare = compare_override if compare_override is not None else _github_workspace_compare(owner, repo, base, head, headers or {})
    prompt = str(data.get("prompt") or "").strip()
    changed_files = [item.get("filename") for item in compare.get("files") or [] if item.get("filename")]

    metadata_request = {
        "task": "Generate pull request metadata from the exact current GitHub branch diff and fill the repository pull request template.",
        "repository": f"{owner}/{repo}",
        "base_branch": base,
        "head_branch": head,
        "user_request": prompt,
        "pull_request_template": template,
        "current_branch_compare": compare,
        "required_output": {
            "title": "A specific concise PR title describing only this compare diff.",
            "body": "The completed repository pull request template, with every template heading retained in its original order and each section filled from the current compare diff.",
        },
        "rules": [
            "Return valid JSON only with exactly the keys title and body.",
            "Use only current_branch_compare as evidence for the changes in this PR.",
            "Do not use prior conversation memory, earlier branches, repository-wide context, old PRs, or unrelated files.",
            "Do not claim a file, resource, pipeline, module, environment, deletion, or addition unless it is present in current_branch_compare.files or its patch.",
            "When pull_request_template is non-empty, copy its markdown structure into body and retain every heading, checklist label, and section in the same order.",
            "Fill each template section with concrete text grounded in current_branch_compare and user_request.",
            "Do not return a free-form PR description when a template is provided.",
            "Do not return the template blank and do not leave instructional placeholders or HTML instructions as the only section content.",
            "If a template section cannot be determined from the diff, write Not applicable or a restrained validation statement instead of inventing details.",
            "The title must not be the generic phrase Terrabot infrastructure changes.",
        ],
    }

    try:
        agent_text = call_named_agent(json.dumps(metadata_request, indent=2), AGENT_NAME)
        parsed = extract_json_from_text(agent_text)
        title = str(parsed.get("title") or "").strip()
        body = str(parsed.get("body") or "").strip()
        if not title or not body:
            raise ValueError("PR metadata agent returned an empty title or body.")
        if title.lower() == "terrabot infrastructure changes":
            raise ValueError("PR metadata agent returned the generic fallback title.")

        if template and not _workspace_pr_body_follows_template(template, body):
            repair_request = {
                "task": "Repair the pull request body so it follows the repository template exactly.",
                "repository": f"{owner}/{repo}",
                "base_branch": base,
                "head_branch": head,
                "user_request": prompt,
                "pull_request_template": template,
                "current_branch_compare": compare,
                "candidate_title": title,
                "candidate_body": body,
                "required_output": {"title": title, "body": "Completed template body"},
                "rules": [
                    "Return valid JSON only with exactly title and body.",
                    "Retain every markdown heading from pull_request_template verbatim and in the same order.",
                    "Retain template checklist labels and fill all sections using only current_branch_compare and user_request.",
                    "Do not return a free-form summary and do not leave the template blank.",
                ],
            }
            repaired_text = call_named_agent(json.dumps(repair_request, indent=2), AGENT_NAME)
            repaired = extract_json_from_text(repaired_text)
            repaired_title = str(repaired.get("title") or title).strip()
            repaired_body = str(repaired.get("body") or "").strip()
            if not repaired_body or not _workspace_pr_body_follows_template(template, repaired_body):
                raise ValueError("PR metadata agent did not preserve the repository pull request template after repair.")
            title, body = repaired_title, repaired_body

        return title[:240], body, compare
    except Exception as exc:
        print(f"Workspace PR metadata generation fallback used: {exc}")
        fallback_title = str(data.get("title") or "").strip()
        if not fallback_title or fallback_title.lower() == "terrabot infrastructure changes":
            if changed_files:
                fallback_title = f"Update {changed_files[0]}" if len(changed_files) == 1 else f"Update {len(changed_files)} repository files"
            else:
                fallback_title = "Update repository changes"
        return fallback_title[:240], _workspace_pr_fallback_body(template, compare, prompt), compare





def _workspace_compare_from_client(data: dict) -> dict:
    changed_files_text = str(data.get("changed_files") or "")
    diff_text = str(data.get("diff") or "")
    files = []
    for line in changed_files_text.splitlines():
        parts = line.strip().split("\t")
        if len(parts) < 2:
            continue
        status_code = parts[0].strip().upper()
        filename = parts[-1].strip()
        if not filename:
            continue
        status = {"A": "added", "D": "removed", "M": "modified", "R": "renamed"}.get(status_code[:1], "modified")
        files.append({
            "filename": filename,
            "status": status,
            "additions": 0,
            "deletions": 0,
            "changes": 0,
            "patch": diff_text[:12000],
        })
    return {
        "status": "ahead",
        "ahead_by": 0,
        "behind_by": 0,
        "total_commits": 0,
        "commits": [],
        "files": files,
        "diff_stat": str(data.get("diff_stat") or ""),
    }


def handle_workspace_pr_metadata_request(data: dict) -> dict:
    owner, repo = _validate_workspace_repo(str(data.get("owner") or ""), str(data.get("repo") or ""))
    head = str(data.get("head") or "").strip()
    base = str(data.get("base") or "main").strip()
    if not head:
        raise ValueError("The PR source branch is required.")

    title, body, compare = _generate_workspace_pr_metadata(
        data=data,
        owner=owner,
        repo=repo,
        base=base,
        head=head,
        compare_override=_workspace_compare_from_client(data),
    )
    return {
        "ok": True,
        "title": title,
        "body": body,
        "changed_files": [item.get("filename") for item in compare.get("files") or []],
    }

def _github_convert_pull_request_to_draft(owner: str, repo: str, pr: dict, headers: dict) -> dict:
    if pr.get("draft"):
        return pr

    node_id = str(pr.get("node_id") or "").strip()
    if not node_id:
        raise RuntimeError("GitHub did not return a pull request node_id required to convert the PR to draft.")

    query = """
mutation ConvertPullRequestToDraft($pullRequestId: ID!) {
  convertPullRequestToDraft(input: {pullRequestId: $pullRequestId}) {
    pullRequest {
      number
      url
      isDraft
    }
  }
}
"""
    response = requests.post(
        f"{GITHUB_API}/graphql",
        headers=headers,
        json={"query": query, "variables": {"pullRequestId": node_id}},
        timeout=30,
    )
    if not response.ok:
        raise _github_request_error(response, "Converting the pull request to draft")

    payload = response.json() or {}
    if payload.get("errors"):
        message = "; ".join(str(item.get("message") or item) for item in payload.get("errors") or [])
        raise RuntimeError(f"Converting the pull request to draft failed: {message}")

    refreshed = requests.get(
        f"{GITHUB_API}/repos/{owner}/{repo}/pulls/{pr.get('number')}",
        headers=headers,
        timeout=30,
    )
    if not refreshed.ok:
        raise _github_request_error(refreshed, "Refreshing the draft pull request")
    return refreshed.json() or pr
def handle_workspace_pr_request(data: dict) -> dict:
    _require_github_token()
    owner, repo = _validate_workspace_repo(str(data.get("owner") or ""), str(data.get("repo") or ""))
    head = str(data.get("head") or "").strip()
    base = str(data.get("base") or "main").strip()
    if not head:
        raise ValueError("The PR source branch is required.")

    headers = github_headers()
    compare_url = f"https://github.com/{owner}/{repo}/compare/{base}...{head}"
    title, body, compare = _generate_workspace_pr_metadata(
        data=data,
        owner=owner,
        repo=repo,
        base=base,
        head=head,
        headers=headers,
    )

    existing_response = requests.get(
        f"{GITHUB_API}/repos/{owner}/{repo}/pulls",
        headers=headers,
        params={"state": "open", "head": f"{owner}:{head}", "base": base},
        timeout=30,
    )
    if not existing_response.ok:
        raise _github_request_error(existing_response, "Checking for an existing pull request")
    existing = existing_response.json() or []
    if existing:
        pr = existing[0]
        update_response = requests.patch(
            f"{GITHUB_API}/repos/{owner}/{repo}/pulls/{pr.get('number')}",
            headers=headers,
            json={"title": title, "body": body},
            timeout=30,
        )
        if not update_response.ok:
            raise _github_request_error(update_response, "Updating the existing pull request metadata")
        pr = update_response.json() or pr
        pr = _github_convert_pull_request_to_draft(owner, repo, pr, headers)
        return {
            "ok": True,
            "existing": True,
            "updated": True,
            "pr_number": pr.get("number"),
            "pr_url": pr.get("html_url"),
            "pr_title": title,
            "compare_url": compare_url,
            "changed_files": [item.get("filename") for item in compare.get("files") or []],
            "draft": bool(pr.get("draft")),
            "reply": "The existing draft pull request title and description were refreshed from the current branch diff.",
        }

    response = requests.post(
        f"{GITHUB_API}/repos/{owner}/{repo}/pulls",
        headers=headers,
        json={"title": title, "head": head, "base": base, "body": body, "draft": True},
        timeout=30,
    )
    if not response.ok:
        raise _github_request_error(response, "Creating the pull request")
    pr = response.json()
    return {
        "ok": True,
        "existing": False,
        "pr_number": pr.get("number"),
        "pr_url": pr.get("html_url"),
        "pr_title": title,
        "compare_url": compare_url,
        "changed_files": [item.get("filename") for item in compare.get("files") or []],
        "draft": bool(pr.get("draft")),
        "reply": "GitHub draft pull request created successfully from the current branch diff.",
    }

def github_headers():
    token = (_ACTIVE_GITHUB_TOKEN.get() or "").strip() or _require_github_token()
    return {
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
    }


def _unique_non_empty(values: list[str]) -> list[str]:
    seen = set()
    result = []
    for value in values or []:
        item = str(value or "").strip().replace("refs/heads/", "")
        if not item or item in seen:
            continue
        seen.add(item)
        result.append(item)
    return result


def github_resolve_base_branch_for_cloud(
    cloud: Any | None,
    branch_name: Optional[str] = None,
    repo_target: Optional[str] = None,
    workflow: Optional[str] = None,
) -> str:
    """Return a real base branch for the target repo.

    Some repositories still use a default branch other than `main`. Teams must
    not fail branch creation only because GITHUB_AWS_BASE_BRANCH defaults to
    main; resolve the live repository default branch and use it as a fallback.
    """
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    configured_branch = (
        branch_name
        or github_base_branch_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
        or ""
    ).strip().replace("refs/heads/", "")

    repo_response = requests.get(
        f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}",
        headers=github_headers(),
        timeout=30,
    )
    if repo_response.status_code == 404:
        raise RuntimeError(
            f"GitHub repository was not found or the token cannot access it. "
            f"Check GITHUB_OWNER='{GITHUB_OWNER}', repo='{repo}', and that the "
            "GitHub App installation includes this repository with Contents read/write permission."
        )
    repo_response.raise_for_status()
    repo_payload = repo_response.json() or {}
    default_branch = str(repo_payload.get("default_branch") or "").strip()

    branch_candidates = _unique_non_empty([
        configured_branch,
        default_branch,
        "main",
        "master",
    ])

    checked = []
    for candidate in branch_candidates:
        checked.append(candidate)
        ref_response = requests.get(
            f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/git/ref/heads/{candidate}",
            headers=github_headers(),
            timeout=30,
        )
        if ref_response.ok:
            if configured_branch and candidate != configured_branch:
                LOGGER.warning(
                    "Configured base branch %s was not found for %s/%s; using live base branch %s.",
                    configured_branch,
                    GITHUB_OWNER,
                    repo,
                    candidate,
                )
            return candidate
        if ref_response.status_code != 404:
            raise _github_request_error(ref_response, "Reading the GitHub base branch")

    raise RuntimeError(
        f"No usable GitHub base branch was found for {GITHUB_OWNER}/{repo}. "
        f"Checked: {', '.join(checked)}. Repo default_branch='{default_branch or 'unknown'}'."
    )


def github_get_base_branch_sha(cloud: Any | None, branch_name: Optional[str] = None, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    base_branch = github_resolve_base_branch_for_cloud(
        cloud,
        branch_name=branch_name,
        repo_target=repo_target,
        workflow=workflow,
    )

    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/git/ref/heads/{base_branch}"
    response = requests.get(url, headers=github_headers(), timeout=30)
    response.raise_for_status()
    return response.json()["object"]["sha"]


def github_create_branch(cloud: Any | None, branch_name: str, base_sha: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/git/refs"
    payload = {"ref": f"refs/heads/{branch_name}", "sha": base_sha}
    response = requests.post(url, headers=github_headers(), json=payload, timeout=30)

    if response.status_code not in (201, 422):
        response.raise_for_status()


def github_get_file_sha(cloud: Any | None, path: str, branch: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)

    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/contents/{path}"
    response = requests.get(url, headers=github_headers(), params={"ref": branch}, timeout=30)

    if response.status_code == 404:
        return None

    response.raise_for_status()
    return response.json().get("sha")


def github_put_file(cloud: Any | None, path: str, content: str, branch: str, commit_message: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/contents/{path}"
    encoded_content = base64.b64encode(content.encode("utf-8")).decode("utf-8")

    payload = {
        "message": commit_message,
        "content": encoded_content,
        "branch": branch,
    }

    sha = github_get_file_sha(
        cloud,
        path,
        branch,
        repo_target=repo_target,
        workflow=workflow,
    )
    if sha:
        payload["sha"] = sha

    response = requests.put(url, headers=github_headers(), json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def _extract_top_level_tf_blocks(tf_content: str) -> list[dict]:
    text = tf_content or ""
    starts = list(re.finditer(
        r'(?m)^\s*(module|resource|data|locals|variable|output)\s+(?:"[^"]+"\s*){0,2}\{',
        text,
    ))

    blocks = []

    for match in starts:
        brace_start = text.find("{", match.end() - 1)
        if brace_start == -1:
            continue

        depth = 0
        in_string = False
        escape = False
        end_idx = -1

        for idx in range(brace_start, len(text)):
            ch = text[idx]
            if in_string:
                if escape:
                    escape = False
                elif ch == "\\":
                    escape = True
                elif ch == '"':
                    in_string = False
                continue

            if ch == '"':
                in_string = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    end_idx = idx + 1
                    break

        if end_idx == -1:
            continue

        block = text[match.start():end_idx].strip()
        header = text[match.start():text.find("{", match.end() - 1)].strip()
        blocks.append({
            "header": re.sub(r"\s+", " ", header),
            "block": block,
        })

    return blocks


def _merge_terraform_content_preserving_existing(existing_content: str, new_content: str) -> str:
    existing = (existing_content or "").replace("\r\n", "\n").rstrip()
    new = (new_content or "").replace("\r\n", "\n").rstrip()

    if not existing:
        return new + "\n"

    if not new:
        return existing + "\n"

    if existing.strip() == new.strip():
        return existing + "\n"

    # If the agent returned the full existing file plus additions, accept it.
    if existing.strip() in new.strip():
        return new + "\n"

    existing_headers = {
        block["header"]
        for block in _extract_top_level_tf_blocks(existing)
    }

    additions = []
    for block in _extract_top_level_tf_blocks(new):
        if block["header"] not in existing_headers:
            additions.append(block["block"])

    if not additions:
        # Do not replace an existing file with a smaller or unrelated generated file.
        return existing + "\n"

    return existing + "\n\n" + "\n\n".join(additions).rstrip() + "\n"


def _is_azure_consumer_variables_tf_path(
    cloud: str,
    path: str,
    repo_target: Optional[str] = None,
    workflow: Optional[str] = None,
) -> bool:
    normalized_path = (path or "").replace("\\", "/").strip("/")
    if normalized_path != "variables.tf" and not normalized_path.endswith("/variables.tf"):
        return False
    try:
        return (
            normalize_cloud(cloud) == "azure"
            and normalize_repo_target("azure", repo_target=repo_target, workflow=workflow) == "tf-azure-hub"
        )
    except Exception:
        return False


def _hcl_curly_brace_balance_for_write(hcl_content: str) -> int:
    """Return unmatched HCL curly-brace depth, ignoring quoted strings.

    This is used as a final write-time safety check for generated variables.tf
    content. It intentionally does not rewrite existing file contents; it only
    detects whether the generated final content is missing trailing closing
    braces before it is sent to GitHub.
    """
    depth = 0
    in_string = False
    escape_next = False

    for ch in hcl_content or "":
        if in_string:
            if escape_next:
                escape_next = False
            elif ch == "\\":
                escape_next = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1

    return depth


def _has_git_conflict_markers(content: str) -> bool:
    return bool(re.search(r'(?m)^(<<<<<<<|=======|>>>>>>>)', content or ""))


def _top_level_tf_block_matches(hcl_content: str) -> list[re.Match]:
    return list(re.finditer(
        r'(?m)^\s*(terraform|provider|module|resource|data|locals|variable|output)\b(?:\s+"[^"]+"){0,2}\s*\{',
        hcl_content or "",
    ))

def _top_level_tf_headers_for_modification(hcl_content: str) -> set[str]:
    headers = set()

    for match in _top_level_tf_block_matches(hcl_content or ""):
        header = match.group(0).rsplit("{", 1)[0].strip()
        header = re.sub(r"\s+", " ", header)
        if header:
            headers.add(header)

    return headers


def _find_balanced_curly_end(hcl_content: str, brace_start: int) -> int:
    """Return index just after the matching close brace line, or -1."""
    text = hcl_content or ""
    if brace_start < 0 or brace_start >= len(text) or text[brace_start] != "{":
        return -1

    depth = 0
    in_string = False
    escape_next = False

    for idx in range(brace_start, len(text)):
        ch = text[idx]
        if in_string:
            if escape_next:
                escape_next = False
            elif ch == "\\":
                escape_next = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                line_end = text.find("\n", idx + 1)
                return len(text) if line_end == -1 else line_end

    return -1


def _repair_unclosed_variable_blocks_in_variables_tf(content: str) -> str:
    """Close incomplete variable blocks before the next top-level block or EOF.

    This is the backend recovery path for the exact merge-conflict failure where
    an editor's "accept both changes" keeps the generated object type body but
    drops the final variable-block close brace. EOF-only repair is insufficient
    once another top-level block follows, so each variable block is repaired at
    its own boundary.
    """
    text = (content or "").replace("\r\n", "\n")
    if not text.strip():
        return text

    matches = _top_level_tf_block_matches(text)
    if not matches:
        return text

    output: list[str] = []
    cursor = 0
    changed = False

    for idx, match in enumerate(matches):
        if match.group(1) != "variable":
            continue

        brace_start = text.find("{", match.end() - 1)
        next_start = matches[idx + 1].start() if idx + 1 < len(matches) else len(text)
        balanced_end = _find_balanced_curly_end(text, brace_start)

        if brace_start == -1 or (balanced_end != -1 and balanced_end <= next_start):
            continue

        segment = text[match.start():next_start]
        missing = _hcl_curly_brace_balance_for_write(segment)
        if missing < 0:
            raise ValueError(
                "Generated variables.tf has extra closing brace(s) inside a variable block; refusing to write malformed Terraform."
            )
        if missing == 0:
            continue

        output.append(text[cursor:next_start].rstrip())
        output.append("\n" + "\n".join("}" for _ in range(missing)))
        cursor = next_start
        changed = True

    if not changed:
        return text

    output.append(text[cursor:])
    return "".join(output)


def _terrabot_marker_line_re(variable_name: str = "") -> re.Pattern:
    name_part = re.escape(_terraform_safe_variable_name(variable_name)) if variable_name else r"[A-Za-z_][A-Za-z0-9_]*"
    return re.compile(rf'^\s*#\s*terrabot:(?:begin|end|close)-variable\s+{name_part}\s*$')


def _variable_block_spans_for_dedupe(tf_content: str) -> list[dict]:
    text = tf_content or ""
    matches = _top_level_tf_block_matches(text)
    spans: list[dict] = []

    for idx, match in enumerate(matches):
        if match.group(1) != "variable":
            continue

        name_match = re.match(r'\s*variable\s+"([^"\n]+)"\s*\{', text[match.start():match.end()], re.IGNORECASE)
        if not name_match:
            continue
        variable_name = _terraform_safe_variable_name(name_match.group(1))
        if not variable_name:
            continue

        brace_start = text.find("{", match.end() - 1)
        next_start = matches[idx + 1].start() if idx + 1 < len(matches) else len(text)
        block_end = _find_balanced_curly_end(text, brace_start)
        if block_end == -1 or block_end > next_start:
            continue

        span_start = match.start()
        prev_line_start = text.rfind("\n", 0, span_start - 1) + 1 if span_start > 0 else 0
        prev_line = text[prev_line_start:span_start].strip()
        if _terrabot_marker_line_re(variable_name).match(prev_line):
            span_start = prev_line_start

        span_end = block_end
        while span_end < len(text):
            newline_offset = 1 if text.startswith("\n", span_end) else 0
            line_start = span_end + newline_offset
            line_end = text.find("\n", line_start)
            if line_end == -1:
                line_end = len(text)
                next_pos = line_end
            else:
                next_pos = line_end + 1
            line = text[line_start:line_end]
            if not line.strip() or _terrabot_marker_line_re(variable_name).match(line):
                span_end = next_pos
                continue
            break

        block_text = text[span_start:span_end]
        normalized = re.sub(r'(?m)^\s*#\s*terrabot:(?:begin|end|close)-variable\s+[^\n]+\n?', '', block_text)
        normalized = re.sub(r'\s+', ' ', normalized).strip()
        spans.append({
            "name": variable_name,
            "start": span_start,
            "end": span_end,
            "text": block_text,
            "normalized": normalized,
            "terrabot_marked": "terrabot:" in block_text,
        })

    return spans


def _dedupe_duplicate_variable_blocks_in_variables_tf(content: str) -> str:
    """Remove duplicate generated variable blocks left by accept-both merges.

    Terraform fails on duplicate variable declarations. We only remove a later
    duplicate when it is Terrabot-marked or byte-normalized equal to the first
    declaration. Different hand-written duplicate declarations are rejected.
    """
    text = (content or "").replace("\r\n", "\n")
    spans = _variable_block_spans_for_dedupe(text)
    if not spans:
        return text

    seen: dict[str, dict] = {}
    remove_ranges: list[tuple[int, int]] = []

    for span in spans:
        name = span["name"]
        if name not in seen:
            seen[name] = span
            continue

        first = seen[name]
        if span["terrabot_marked"] or first["terrabot_marked"] or span["normalized"] == first["normalized"]:
            remove_ranges.append((span["start"], span["end"]))
            continue

        raise ValueError(
            f'Generated variables.tf contains multiple different variable "{name}" declarations; resolve the duplicate before committing.'
        )

    if not remove_ranges:
        return text

    for start, end in sorted(remove_ranges, reverse=True):
        text = text[:start].rstrip() + "\n\n" + text[end:].lstrip("\n")

    return text.rstrip() + "\n"


def _repair_unclosed_variables_tf_content_for_write(
    existing_content: str | None,
    generated_content: str,
    path: str,
) -> str:
    """Return balanced variables.tf content or reject malformed Terraform.

    This fixes the conflict-resolution case where "accept both changes" keeps
    the generated object-type body but drops the final variable-block close
    brace. It also removes duplicate Terrabot-generated variable blocks that can
    be left by accepting both sides of an EOF append conflict.
    """
    del existing_content

    normalized_path = (path or "").replace("\\", "/").strip("/")
    if normalized_path != "variables.tf" and not normalized_path.endswith("/variables.tf"):
        return (generated_content or "").replace("\r\n", "\n").rstrip() + "\n"

    generated = (generated_content or "").replace("\r\n", "\n").rstrip()

    if not generated.strip():
        return "\n"

    if _has_git_conflict_markers(generated):
        raise ValueError(
            f"Generated {path} still contains Git conflict markers; resolve the conflict before committing."
        )

    generated = _repair_unclosed_variable_blocks_in_variables_tf(generated)

    balance = _hcl_curly_brace_balance_for_write(generated)

    if balance < 0:
        raise ValueError(
            f"Generated {path} has extra closing brace(s); refusing to write malformed Terraform."
        )

    if balance > 0:
        generated = generated.rstrip() + "\n" + "\n".join("}" for _ in range(balance))

    generated = _dedupe_duplicate_variable_blocks_in_variables_tf(generated)

    if _hcl_curly_brace_balance_for_write(generated) != 0:
        raise ValueError(
            f"Generated {path} is still unbalanced after variables.tf finalization; refusing to write malformed Terraform."
        )

    for match in re.finditer(
        r'(?m)^\s*variable\s+"([^"\n]+)"\s*\{',
        generated,
        re.IGNORECASE,
    ):
        variable_name = match.group(1).strip()
        if not variable_name:
            continue

        block = _extract_tf_variable_block(generated, variable_name)
        if not block:
            raise ValueError(
                f'Generated {path} contains an incomplete variable "{variable_name}" block; refusing to write malformed Terraform.'
            )

        if _hcl_curly_brace_balance_for_write(block) != 0:
            raise ValueError(
                f'Generated {path} contains an unbalanced variable "{variable_name}" block; refusing to write malformed Terraform.'
            )

    return generated.rstrip() + "\n"

def _validate_full_file_modification_preserves_existing(
    existing_content: str,
    generated_content: str,
    path: str,
) -> None:
    existing = (existing_content or "").replace("\r\n", "\n").strip()
    generated = (generated_content or "").replace("\r\n", "\n").strip()

    if not generated:
        raise ValueError(
            f"Generated modification for {path} is empty. "
            "Refusing to remove the whole file by accident."
        )

    if path.endswith(".tf"):
        existing_headers = _top_level_tf_headers_for_modification(existing)
        generated_headers = _top_level_tf_headers_for_modification(generated)

        if existing_headers:
            preserved = existing_headers & generated_headers
            removed = existing_headers - generated_headers
            added = generated_headers - existing_headers

            # This catches the exact bad case where the agent replaces:
            # module "password_policy" { ... }
            # with terraform/provider/resource scaffolding.
            if not preserved:
                raise ValueError(
                    f"Generated modification for {path} does not preserve any existing Terraform block. "
                    "Modification workflows must edit matched existing code, not replace the file with unrelated Terraform."
                )

            # A "modification" workflow tag does not always mean "edit only,
            # never add": legitimate creation-via-append requests (e.g.
            # "create a second GRS storage account under a new module
            # instance name", "add a second instance", or any
            # already-exists -> create-under-a-new-name follow-up) also get
            # written through this path because the target file already
            # exists on disk. Blanket-rejecting any added top-level block
            # broke that entire class of legitimate creation request.
            #
            # A new block is safe to accept as long as the write is provably
            # additive: nothing existing was removed, and every line of the
            # existing file still appears, unchanged and in order, inside the
            # generated content. That is exactly the shape of a legitimate
            # "append a new sibling resource/module" change. Only reject when
            # the addition looks like a destructive rewrite (existing blocks
            # were also removed, or existing content was not preserved
            # verbatim) — that is the real hallucinated-replacement failure
            # this check exists to catch.
            if added:
                if removed or not _teams_generated_preserves_existing_lines(existing, generated):
                    raise ValueError(
                        f"Generated modification for {path} introduces new top-level Terraform blocks "
                        f"({', '.join(sorted(added))}) without cleanly preserving the existing file. "
                        "A safe change must keep every existing line untouched and only append new "
                        "block(s); regenerate so the existing content is preserved exactly."
                    )

            # Allow targeted delete/update, but reject broad replacement.
            if len(removed) > max(3, len(existing_headers) // 2):
                raise ValueError(
                    f"Generated modification for {path} removes too many existing Terraform blocks. "
                    "The backend only allows targeted update/delete/fix edits."
                )

    if path.endswith(".tfvars"):
        try:
            existing_names = set(_extract_top_level_hcl_assignment_names(existing))
            generated_names = set(_extract_top_level_hcl_assignment_names(generated))
        except Exception:
            existing_names = set()
            generated_names = set()

        if existing_names:
            removed = existing_names - generated_names

            if len(removed) > max(3, len(existing_names) // 2):
                raise ValueError(
                    f"Generated modification for {path} removes too many existing tfvars assignments. "
                    "The backend only allows targeted variable value edits."
                )

def github_put_file_if_changed(
    cloud: str,
    path: str,
    content: str,
    branch: str,
    commit_message: str,
    repo_target: Optional[str] = None,
    workflow: Optional[str] = None,
):
    """Write Foundry-generated content exactly; never synthesize Terraform.

    The backend may compare, validate, and transport the agent's final file,
    but it must not merge blocks, repair braces, normalize tfvars, toggle
    Boolean values, or otherwise create/modify Terraform on the agent's behalf.
    """
    existing_content = github_get_file_content(
        cloud,
        path,
        branch,
        repo_target=repo_target,
        workflow=workflow,
    )
    final_content = str(content or "")

    normalized_existing = (existing_content or "").replace("\r\n", "\n").strip()
    normalized_new = final_content.replace("\r\n", "\n").strip()
    if existing_content is not None and normalized_existing == normalized_new:
        return {"changed": False, "path": path, "result": None}

    # Validation is allowed; mutation is not. Foundry must correct invalid HCL.
    if path.endswith((".tf", ".tfvars")):
        _validate_hcl_content_complete(path, final_content)
        if _has_git_conflict_markers(final_content):
            raise ValueError(f"Generated {path} contains Git conflict markers.")

    result = github_put_file(
        cloud=cloud,
        path=path,
        content=final_content,
        branch=branch,
        commit_message=commit_message,
        repo_target=repo_target,
        workflow=workflow,
    )
    return {"changed": True, "path": path, "result": result}

def github_create_pull_request(cloud: Any | None, branch_name: str, title: str, body: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    base_branch = github_resolve_base_branch_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/pulls"
    payload = {
        "title": title,
        "head": branch_name,
        "base": base_branch,
        "body": body,
    }
    response = requests.post(url, headers=github_headers(), json=payload, timeout=30)

    if response.status_code == 422:
        existing = github_find_pr_by_branch(
            cloud,
            branch_name,
            state="open",
            repo_target=repo_target,
            workflow=workflow,
        )
        if existing:
            return existing
        raise RuntimeError(
            "GitHub could not create a pull request for this branch. "
            "This usually happens when the branch already has a closed or merged PR, or when there are no new commits to open a PR."
        )

    response.raise_for_status()
    return response.json()



def github_find_pr_by_branch(cloud: Any | None, branch_name: str, state: str = "open", repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    base_branch = github_base_branch_for_cloud(cloud, repo_target=repo_target, workflow=workflow)

    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/pulls"
    response = requests.get(
        url,
        headers=github_headers(),
        params={
            "state": state,
            "head": f"{GITHUB_OWNER}:{branch_name}",
            "base": base_branch,
        },
        timeout=30,
    )
    response.raise_for_status()
    prs = response.json()
    return prs[0] if prs else None


def github_branch_exists(cloud: Any | None, branch_name: str, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> bool:
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)

    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/git/ref/heads/{branch_name}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return False

    response.raise_for_status()
    return True

def github_list_matching_branches(cloud: Any | None, prefix: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)

    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/git/matching-refs/heads/{prefix}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return []

    response.raise_for_status()
    refs = response.json() or []
    branches = []
    for item in refs:
        ref = item.get("ref", "")
        if ref.startswith("refs/heads/"):
            branches.append(ref.replace("refs/heads/", "", 1))
    return branches

def github_folder_exists(cloud: Any | None, path: str, branch: str, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> bool:
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)

    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/contents/{path}"
    response = requests.get(url, headers=github_headers(), params={"ref": branch}, timeout=30)

    if response.status_code == 404:
        return False

    response.raise_for_status()
    return True


def github_get_directory_listing(cloud: Any | None, path: str, branch: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)

    normalized_path = (path or "").strip("/")
    if normalized_path in {"", "."}:
        url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/contents"
    else:
        url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/contents/{normalized_path}"
    response = requests.get(url, headers=github_headers(), params={"ref": branch}, timeout=30)

    if response.status_code == 404:
        return []

    response.raise_for_status()
    data = response.json()
    return data if isinstance(data, list) else [data]


def github_get_file_content(cloud: Any | None, path: str, branch: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    url = f"{GITHUB_API}/repos/{GITHUB_OWNER}/{repo}/contents/{path}"
    response = requests.get(url, headers=github_headers(), params={"ref": branch}, timeout=30)

    if response.status_code == 404:
        return None

    response.raise_for_status()
    data = response.json()

    encoded = data.get("content")
    if not encoded:
        return None

    return base64.b64decode(encoded).decode("utf-8")

def _github_get_repo_metadata_base(owner: str, repo: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return None

    response.raise_for_status()
    return response.json()

def github_get_repo(owner: str, repo: str) -> Optional[dict]:
    url = f"{GITHUB_API}/repos/{owner}/{repo}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return None

    response.raise_for_status()
    return response.json()


def github_get_repo_default_branch(owner: str, repo: str) -> Optional[str]:
    repo_data = github_get_repo(owner, repo)
    if not repo_data:
        return None
    return repo_data.get("default_branch")


def github_get_contents(owner: str, repo: str, path: str = "", ref: Optional[str] = None):
    normalized_path = (path or "").strip("/")
    if normalized_path:
        url = f"{GITHUB_API}/repos/{owner}/{repo}/contents/{normalized_path}"
    else:
        url = f"{GITHUB_API}/repos/{owner}/{repo}/contents"

    params = {}
    if ref:
        params["ref"] = ref

    response = requests.get(url, headers=github_headers(), params=params or None, timeout=30)
    if response.status_code == 404:
        return [] if not normalized_path else None

    response.raise_for_status()
    return response.json()


def github_get_file_content_by_repo(owner: str, repo: str, path: str, ref: Optional[str] = None) -> Optional[str]:
    data: Any = github_get_contents(owner, repo, path=path, ref=ref)
    if not isinstance(data, dict):
        return None

    encoded = data.get("content")
    if not encoded:
        return None

    return base64.b64decode(encoded).decode("utf-8")

def github_get_base_branch_sha_by_repo(owner: str, repo: str, branch_name: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/git/ref/heads/{branch_name}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        raise RuntimeError(
            f"GitHub repo or branch not found. owner='{owner}', repo='{repo}', branch='{branch_name}'."
        )

    response.raise_for_status()
    return response.json()["object"]["sha"]


def github_branch_exists_by_repo(owner: str, repo: str, branch_name: str) -> bool:
    url = f"{GITHUB_API}/repos/{owner}/{repo}/git/ref/heads/{branch_name}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return False

    response.raise_for_status()
    return True


def github_create_branch_by_repo(owner: str, repo: str, branch_name: str, base_sha: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/git/refs"
    payload = {"ref": f"refs/heads/{branch_name}", "sha": base_sha}
    response = requests.post(url, headers=github_headers(), json=payload, timeout=30)

    if response.status_code not in (201, 422):
        response.raise_for_status()


def github_get_file_sha_by_repo(owner: str, repo: str, path: str, branch: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/contents/{path}"
    response = requests.get(url, headers=github_headers(), params={"ref": branch}, timeout=30)

    if response.status_code == 404:
        return None

    response.raise_for_status()
    return response.json().get("sha")


def github_put_file_by_repo(owner: str, repo: str, path: str, content: str, branch: str, commit_message: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/contents/{path}"
    encoded_content = base64.b64encode(content.encode("utf-8")).decode("utf-8")

    payload = {
        "message": commit_message,
        "content": encoded_content,
        "branch": branch,
    }

    sha = github_get_file_sha_by_repo(owner, repo, path, branch)
    if sha:
        payload["sha"] = sha

    response = requests.put(url, headers=github_headers(), json=payload, timeout=30)
    response.raise_for_status()
    return response.json()


def github_get_file_content_by_repo_branch(owner: str, repo: str, path: str, branch: str):
    return github_get_file_content_by_repo(owner, repo, path, ref=branch)


def github_put_file_if_changed_by_repo(owner: str, repo: str, path: str, content: str, branch: str,  commit_message: str):
    existing_content = github_get_file_content_by_repo_branch(owner, repo, path, branch )

    normalized_existing = (existing_content or "").replace("\r\n", "\n").strip()
    normalized_new = (content or "").replace("\r\n", "\n").strip()
    
    if existing_content is not None and normalized_existing == normalized_new:
      return {
        "changed": False,
        "path": path,
        "result": None,
    }

    result = github_put_file_by_repo(
        owner=owner,
        repo=repo,
        path=path,
        content=content,
        branch=branch,
        commit_message=commit_message,
    )

    return {
        "changed": True,
        "path": path,
        "result": result,
    }


def github_find_pr_by_branch_by_repo(owner: str, repo: str, branch_name: str, base_branch: str, state: str = "open"):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/pulls"
    response = requests.get(
        url,
        headers=github_headers(),
        params={
            "state": state,
            "head": f"{owner}:{branch_name}",
            "base": base_branch,
        },
        timeout=30,
    )
    response.raise_for_status()
    prs = response.json()
    return prs[0] if prs else None


def github_create_pull_request_by_repo(owner: str, repo: str, branch_name: str, base_branch: str, title: str, body: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/pulls"
    payload = {
        "title": title,
        "head": branch_name,
        "base": base_branch,
        "body": body,
    }

    response = requests.post(url, headers=github_headers(), json=payload, timeout=30)

    if response.status_code == 422:
        existing = github_find_pr_by_branch_by_repo(
            owner=owner,
            repo=repo,
            branch_name=branch_name,
            base_branch=base_branch,
            state="open",
        )
        if existing:
            return existing

    response.raise_for_status()
    return response.json()



def github_get_pull_request_by_repo(owner: Optional[str], repo: Optional[str], pr_number: int):
    if not owner or not repo or not pr_number:
        return None

    url = f"{GITHUB_API}/repos/{owner}/{repo}/pulls/{int(pr_number)}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return None

    response.raise_for_status()
    return response.json()


def github_list_pull_request_files_by_repo(owner: Optional[str], repo: Optional[str], pr_number: int) -> list[dict]:
    if not owner or not repo or not pr_number:
        return []

    files = []
    page = 1

    while True:
        url = f"{GITHUB_API}/repos/{owner}/{repo}/pulls/{int(pr_number)}/files"
        response = requests.get(
            url,
            headers=github_headers(),
            params={"per_page": 100, "page": page},
            timeout=30,
        )

        if response.status_code == 404:
            return []

        response.raise_for_status()
        batch = response.json() or []
        files.extend([item for item in batch if isinstance(item, dict)])

        if len(batch) < 100:
            break
        page += 1

    return files


def github_list_matching_branches_by_repo(owner: str, repo: str, prefix: str) -> list[str]:
    if not owner or not repo or not prefix:
        return []

    url = f"{GITHUB_API}/repos/{owner}/{repo}/git/matching-refs/heads/{prefix}"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return []

    response.raise_for_status()
    refs = response.json() or []
    branches = []
    for item in refs:
        ref = item.get("ref", "") if isinstance(item, dict) else ""
        if ref.startswith("refs/heads/"):
            branches.append(ref.replace("refs/heads/", "", 1))
    return branches


def github_get_pull_request(cloud: Any | None, pr_number: int, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    return github_get_pull_request_by_repo(GITHUB_OWNER, repo, pr_number)


def github_list_pull_request_files(cloud: Any | None, pr_number: int, repo_target: Optional[str] = None, workflow: Optional[str] = None) -> list[dict]:
    repo = github_repo_for_cloud(cloud, repo_target=repo_target, workflow=workflow)
    return github_list_pull_request_files_by_repo(GITHUB_OWNER, repo, pr_number)


def github_search_code(query: str, per_page: int = 20) -> list:
    url = f"{GITHUB_API}/search/code"
    response = requests.get(
        url,
        headers=github_headers(),
        params={"q": query, "per_page": max(1, min(int(per_page or 20), 100))},
        timeout=30,
    )

    if response.status_code == 404:
        return []

    response.raise_for_status()
    data = response.json() or {}
    return data.get("items") or []


def _unique_branch_names(branches: list[str]) -> list[str]:
    seen = set()
    result = []
    for branch in branches or []:
        name = (branch or "").strip()
        if not name or name in seen:
            continue
        seen.add(name)
        result.append(name)
    return result


def _github_list_repo_branches_from_refs(owner: str, repo: str) -> list[str]:
    """Fallback branch listing through Git refs.

    /branches is the primary API. /git/matching-refs/heads is a second
    backend-only read from GitHub and still returns only real branch refs.
    """
    url = f"{GITHUB_API}/repos/{owner}/{repo}/git/matching-refs/heads"
    response = requests.get(url, headers=github_headers(), timeout=30)

    if response.status_code == 404:
        return []

    response.raise_for_status()
    refs = response.json() or []
    branches = []
    for item in refs:
        if not isinstance(item, dict):
            continue
        ref = item.get("ref") or ""
        if ref.startswith("refs/heads/"):
            branches.append(ref.replace("refs/heads/", "", 1))
    return branches


def github_list_repo_branches(owner: str, repo: str) -> list[str]:
    branches = []
    page = 1

    while True:
        url = f"{GITHUB_API}/repos/{owner}/{repo}/branches"
        response = requests.get(
            url,
            headers=github_headers(),
            params={"per_page": 100, "page": page},
            timeout=30,
        )

        if response.status_code == 404:
            return []

        response.raise_for_status()
        batch = response.json() or []
        if not batch:
            break

        for item in batch:
            name = item.get("name") if isinstance(item, dict) else None
            if name:
                branches.append(name)

        if len(batch) < 100:
            break
        page += 1

    try:
        branches.extend(_github_list_repo_branches_from_refs(owner, repo))
    except Exception as ref_error:
        print(f"Azure module branch refs fallback skipped {owner}/{repo}: {ref_error}")

    return _unique_branch_names(branches)


def _list_tf_files_by_repo_ref(owner: str, repo: str, ref: str) -> list[str]:
    results = []

    def walk(path: str = ""):
        items = github_get_contents(owner, repo, path=path, ref=ref)
        if isinstance(items, dict):
            items = [items]

        for item in items or []:
            if not isinstance(item, dict):
                continue

            item_type = item.get("type")
            item_path = item.get("path") or ""

            if item_type == "dir":
                walk(item_path)
            elif item_type == "file" and item_path.endswith(".tf"):
                results.append(item_path)

    walk("")
    return results


def get_best_module_branch_with_inputs(repo_owner: str, repo_name: str):
    """
    Try the default/main branch first, then other branches, and return the branch
    with the strongest verified Terraform variable coverage.
    """
    repo_owner = (repo_owner or "").strip()
    repo_name = (repo_name or "").strip()
    if not repo_owner or not repo_name:
        return []

    repo_metadata = github_get_repo(repo_owner, repo_name)
    default_branch = (repo_metadata or {}).get("default_branch") or "main"
    branches = github_list_repo_branches(repo_owner, repo_name)

    ordered_branches = []
    for candidate in [default_branch, "main"] + branches:
        if candidate and candidate not in ordered_branches:
            ordered_branches.append(candidate)

    best_branch = None
    best_inputs = []
    best_required = []
    best_score = -1

    for branch in ordered_branches:
        try:
            tf_files = _list_tf_files_by_repo_ref(repo_owner, repo_name, branch)
        except Exception:
            continue

        inputs = []
        required = []

        for tf_path in tf_files:
            try:
                content = github_get_file_content_by_repo(repo_owner, repo_name, tf_path, ref=branch)
            except Exception:
                content = None

            if not content:
                continue

            inputs.extend(_extract_tf_variable_names_from_text(content))
            required.extend(_extract_required_variable_names_from_text(content))
            for match in re.finditer(r'variable\s+"([^"]+)"\s*\{', content, re.IGNORECASE):
                variable_name = match.group(1)
                brace_start = content.find("{", match.end() - 1)
                if brace_start == -1:
                    continue

                depth = 0
                in_string = False
                escape_next = False
                block = ""

                for idx in range(brace_start, len(content)):
                    ch = content[idx]
                    if in_string:
                        if escape_next:
                            escape_next = False
                        elif ch == "\\":
                            escape_next = True
                        elif ch == '"':
                            in_string = False
                        continue

                    if ch == '"':
                        in_string = True
                    elif ch == "{":
                        depth += 1
                    elif ch == "}":
                        depth -= 1
                        if depth == 0:
                            block = content[match.start():idx + 1]
                            break

                if block and not re.search(r'^\s*default\s*=', block, re.MULTILINE | re.IGNORECASE):
                    required.append(variable_name)

        inputs = list(dict.fromkeys(inputs))
        required = [name for name in list(dict.fromkeys(required)) if name in inputs]

        score = len(inputs) * 10 + len(required)
        if branch == default_branch:
            score += 2
        elif branch == "main":
            score += 1

        if score > best_score:
            best_score = score
            best_branch = branch
            best_inputs = inputs
            best_required = required


    return best_branch, best_inputs, best_required


def get_module_branch_options_with_inputs(repo_owner: Optional[str], repo_name: Optional[str]) -> list[dict]:
    """Return real GitHub branches for a module repo with input summaries.

    Branch names are taken only from GitHub APIs. No model output is used for
    branch discovery. A branch is included even if Terraform inspection fails,
    so the user can still see the real branch list.
    """
    repo_owner = (repo_owner or "").strip()
    repo_name = (repo_name or "").strip()
    if not repo_owner or not repo_name:
        return []

    repo_metadata = github_get_repo(repo_owner, repo_name)
    default_branch = (repo_metadata or {}).get("default_branch") or "main"
    branches = github_list_repo_branches(repo_owner, repo_name)

    ordered_branches = []
    for candidate in [default_branch, "main"] + list(branches or []):
        candidate = (candidate or "").strip()
        if candidate and candidate not in ordered_branches:
            ordered_branches.append(candidate)

    options = []

    for branch in ordered_branches:
        inspection_error = ""
        try:
            tf_files = _list_tf_files_by_repo_ref(repo_owner, repo_name, branch)
        except Exception as branch_error:
            inspection_error = str(branch_error)
            print(f"Azure module branch inspection could not read {repo_owner}/{repo_name}@{branch}: {branch_error}")
            tf_files = []

        inputs = []
        required = []
        outputs = []
        variables_tf_paths = []

        for tf_path in tf_files:
            lower_path = (tf_path or "").lower()
            if lower_path.endswith("variables.tf"):
                variables_tf_paths.append(tf_path)

            try:
                content = github_get_file_content_by_repo(repo_owner, repo_name, tf_path, ref=branch)
            except Exception:
                content = None

            if not content:
                continue

            inputs.extend(_extract_tf_variable_names_from_text(content))
            required.extend(_extract_required_variable_names_from_text(content))
            outputs.extend(re.findall(r'output\s+"([^"]+)"', content, re.IGNORECASE))

            for match in re.finditer(r'variable\s+"([^"]+)"\s*\{', content, re.IGNORECASE):
                variable_name = match.group(1)
                brace_start = content.find("{", match.end() - 1)
                if brace_start == -1:
                    continue

                depth = 0
                in_string = False
                escape_next = False
                block = ""

                for idx in range(brace_start, len(content)):
                    ch = content[idx]
                    if in_string:
                        if escape_next:
                            escape_next = False
                        elif ch == "\\":
                            escape_next = True
                        elif ch == '"':
                            in_string = False
                        continue

                    if ch == '"':
                        in_string = True
                    elif ch == "{":
                        depth += 1
                    elif ch == "}":
                        depth -= 1
                        if depth == 0:
                            block = content[match.start():idx + 1]
                            break

                if block and not re.search(r'^\s*default\s*=', block, re.MULTILINE | re.IGNORECASE):
                    required.append(variable_name)

        inputs = list(dict.fromkeys(inputs))
        required = [name for name in list(dict.fromkeys(required)) if name in inputs]
        outputs = list(dict.fromkeys(outputs))
        variables_tf_paths = list(dict.fromkeys(variables_tf_paths))

        score = len(inputs) * 10 + len(required)
        if variables_tf_paths:
            score += 5
        if branch == default_branch:
            score += 2
        elif branch == "main":
            score += 1

        options.append({
            "branch": branch,
            "is_default": branch == default_branch,
            "is_main": branch == "main",
            "tf_files": list(tf_files or []),
            "variables_tf_paths": variables_tf_paths,
            "has_variables_tf": bool(variables_tf_paths),
            "inputs_detected": inputs,
            "required_inputs_detected": required,
            "outputs_detected": outputs,
            "score": score,
            "inspection_error": inspection_error,
        })

    options.sort(
        key=lambda item: (
            0 if item.get("inputs_detected") else 1,
            0 if item.get("has_variables_tf") else 1,
            -int(item.get("score") or 0),
            0 if item.get("is_default") else 1,
            item.get("branch") or "",
        )
    )

    if options:
        options[0]["recommended"] = True

    return options


def should_require_azure_module_branch_selection(branch_options: list[dict]) -> bool:
    """Always require an explicit user-selected module branch/ref.

    This prevents silently falling back to main/default or a guessed "best"
    branch when variables.tf lives on another real GitHub branch.
    """
    return True


def build_azure_module_branch_discovery(discovery: dict, match: dict) -> dict:
    match = match or {}
    if match.get("repo_owner") and match.get("repo_name"):
        branch_options = get_module_branch_options_with_inputs(
            match.get("repo_owner"),
            match.get("repo_name"),
        )
    else:
        branch_options = []

    branch_discovery = dict(discovery or {})
    branch_discovery["decision_state"] = "azure_module_branch_selection"
    branch_discovery["selected_match"] = match
    branch_discovery["branch_options"] = branch_options
    branch_discovery["branch_selection_required"] = should_require_azure_module_branch_selection(branch_options)
    return branch_discovery


def _manual_branch_candidates_from_reply(reply: str) -> list[str]:
    raw = (reply or "").strip().strip("`'\"")
    if not raw:
        return []

    candidates = [raw]
    prefix_match = re.match(
        r"^(?:use|select|choose|pick|branch|ref)\s+(.+)$",
        raw,
        re.IGNORECASE,
    )
    if prefix_match:
        candidates.append(prefix_match.group(1).strip().strip("`'\""))

    result = []
    for candidate in candidates:
        candidate = (candidate or "").strip().strip("`'\"")
        lower = normalize_yes_no_reply(candidate)

        if not candidate or lower in AFFIRMATIVE_REPLIES or lower in NEGATIVE_REPLIES:
            continue
        if re.fullmatch(r"#?\d+", candidate):
            continue
        if re.search(r"\s", candidate):
            continue
        if not re.fullmatch(r"[A-Za-z0-9._/-]+", candidate):
            continue
        if candidate not in result:
            result.append(candidate)

    return result


def resolve_manual_azure_module_branch_from_reply(reply: str, match: dict) -> str:
    match = match or {}
    owner = (match.get("repo_owner") or GITHUB_OWNER or "").strip()
    repo = (match.get("repo_name") or "").strip()
    if not owner or not repo:
        return ""

    for candidate in _manual_branch_candidates_from_reply(reply):
        try:
            if github_branch_exists_by_repo(owner, repo, candidate):
                return candidate
        except Exception as branch_error:
            print(f"Manual Azure module branch check failed {owner}/{repo}@{candidate}: {branch_error}")

    return ""


def azure_context_has_verified_inputs_for_branch(
    retrieved_module_context: list,
    repo_full_name: str,
    selected_module_ref: str,
) -> bool:
    repo_full_name = (repo_full_name or "").strip().lower()
    selected_module_ref = (selected_module_ref or "").strip()

    for item in retrieved_module_context or []:
        if not isinstance(item, dict):
            continue
        if repo_full_name and (item.get("repo_full_name") or "").strip().lower() != repo_full_name:
            continue
        if selected_module_ref and (item.get("resolved_ref") or "").strip() != selected_module_ref:
            continue
        if item.get("inputs_detected"):
            return True

    return False


def add_grounded_azure_context_for_match(
    match: dict,
    selected_module_ref: str,
    retrieved_module_context: list,
    retrieved_value_context: list,
) -> tuple[list[dict], list[dict]]:
    approved_consumer_repos = get_approved_azure_consumer_repos()
    approved_repo_default_branches = {
        repo_name: GITHUB_AZURE_BASE_BRANCH
        for repo_name in approved_consumer_repos
    }

    grounded_module_context, grounded_value_context = build_grounded_azure_contexts(
        match,
        github_get_repo_default_branch=github_get_repo_default_branch,
        github_get_contents=github_get_contents,
        github_get_file_content_by_repo=github_get_file_content_by_repo,
        github_search_code=github_search_code,
        github_verify_repo_exists=github_verify_repo_exists,
        approved_consumer_repos=approved_consumer_repos,
        approved_repo_default_branches=approved_repo_default_branches,
        # Do not auto-select a best branch here. The selected ref must come
        # from the explicit branch-selection prompt and is used verbatim for
        # module source and variables.tf retrieval.
        get_best_module_branch_with_inputs=None,
        selected_module_ref=selected_module_ref,
    )

    if grounded_module_context:
        existing_keys = {
            item.get("repo_full_name")
            for item in retrieved_module_context
            if isinstance(item, dict)
        }
        for item in grounded_module_context:
            if item.get("repo_full_name") not in existing_keys:
                retrieved_module_context = list(retrieved_module_context or [])
                retrieved_module_context.append(item)
                existing_keys.add(item.get("repo_full_name"))

    if grounded_value_context:
        retrieved_value_context = list(retrieved_value_context or [])
        retrieved_value_context.extend(grounded_value_context)

    return retrieved_module_context, retrieved_value_context


def github_verify_repo_exists(full_name: str) -> bool:
    owner_repo = (full_name or "").strip().split("/", 1)
    if len(owner_repo) != 2:
        return False
    owner, repo = owner_repo
    return github_get_repo(owner, repo) is not None


def github_get_repo_metadata(owner: str, repo: str) -> Optional[dict]:
    return github_get_repo(owner, repo)


def github_repo_exists(owner: str, repo: str) -> bool:
    return github_verify_repo_exists(f"{owner}/{repo}")


def github_list_tf_files_recursive(
    cloud: str,
    root_path: str,
    branch: str,
    repo_target: Optional[str] = None,
    workflow: Optional[str] = None,
):
    results = []

    def walk(current_path: str):
        items = github_get_directory_listing(
            cloud,
            current_path,
            branch,
            repo_target=repo_target,
            workflow=workflow,
        )
        for item in items:
            item_type = item.get("type")
            item_path = item.get("path", "")
            if item_type == "dir":
                walk(item_path)
                continue
            if item_type == "file" and item_path.endswith(".tf"):
                results.append(item_path)

    walk(root_path or ".")
    return results

def auth_headers_ok(headers) -> bool:
    return True

def github_headers_for_repo():
    return {
        "Authorization": f"Bearer {GITHUB_TOKEN}",
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
    }


def github_list_issue_comments(owner: str, repo: str, issue_number: int):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/issues/{issue_number}/comments"
    response = requests.get(url, headers=github_headers_for_repo(), timeout=30)
    response.raise_for_status()
    return response.json()


def github_create_issue_comment(owner: str, repo: str, issue_number: int, body: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/issues/{issue_number}/comments"
    response = requests.post(
        url,
        headers=github_headers_for_repo(),
        json={"body": body},
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def github_update_issue_comment(owner: str, repo: str, comment_id: int, body: str):
    url = f"{GITHUB_API}/repos/{owner}/{repo}/issues/comments/{comment_id}"
    response = requests.patch(
        url,
        headers=github_headers_for_repo(),
        json={"body": body},
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def github_upsert_pr_summary_comment(owner: str, repo: str, pr_number: int, body: str):
    comments = github_list_issue_comments(owner, repo, pr_number)

    existing = None
    for comment in comments:
        if GITHUB_PR_COMMENT_MARKER in (comment.get("body") or ""):
            existing = comment
            break

    final_body = f"{GITHUB_PR_COMMENT_MARKER}\n{body}"

    if existing:
        return github_update_issue_comment(owner, repo, existing["id"], final_body)

    return github_create_issue_comment(owner, repo, pr_number, final_body)

def azure_devops_headers():
    pat = (AZDO_PAT or "").strip()
    if not pat:
        raise RuntimeError("Missing AZDO_PAT environment variable.")

    token = base64.b64encode(f":{pat}".encode("utf-8")).decode("ascii")
    return {
        "Authorization": f"Basic {token}",
        "Accept": "application/json",
        "Content-Type": "application/json",
    }

def trigger_test_branch_pipeline_for_pr(
    repo_owner: Optional[str],
    repo_name: Optional[str],
    pr_number: int,
    source_branch: str,
    target_branch: str,
):
    repo_owner = (repo_owner or "").strip()
    repo_name = (repo_name or "").strip()
    if not repo_owner or not repo_name:
        raise RuntimeError("PR repository owner and name are required for the Azure DevOps pipeline.")

    missing = []
    if not AZDO_ORG:
        missing.append("AZDO_ORG")
    if not AZDO_PROJECT:
        missing.append("AZDO_PROJECT")
    if not AZDO_PIPELINE_ID:
        missing.append("AZDO_PIPELINE_ID")
    if not AZDO_PAT:
        missing.append("AZDO_PAT")

    if missing:
        raise RuntimeError(
            "Missing Azure DevOps pipeline settings: " + ", ".join(missing)
        )

    pipeline_branch = (AZDO_PIPELINE_BRANCH or "terrabot-test").replace("refs/heads/", "").strip()
    source_branch = (source_branch or "").replace("refs/heads/", "").strip()
    target_branch = (target_branch or "").replace("refs/heads/", "").strip()

    if not source_branch:
        raise RuntimeError("PR source branch was empty.")
    if not target_branch:
        raise RuntimeError("PR target branch was empty.")

    url = (
        f"https://dev.azure.com/{AZDO_ORG}/{AZDO_PROJECT}"
        f"/_apis/build/builds?api-version={AZDO_API_VERSION}"
    )

    payload = {
        "definition": {
            "id": int(AZDO_PIPELINE_ID or 0)
        },
        "sourceBranch": f"refs/heads/{pipeline_branch}",
        "variables": {
            "PR_REPO_OWNER": {"value": repo_owner},
            "PR_REPO_NAME": {"value": repo_name},
            "PR_NUMBER": {"value": str(pr_number)},
            "PR_SOURCE_BRANCH": {"value": source_branch},
            "PR_TARGET_BRANCH": {"value": target_branch},
            "PR_IS_BACKEND_TRIGGERED": {"value": "true"},
            "PIPELINE_CODE_BRANCH": {"value": pipeline_branch},
        }
    }

    response = requests.post(
        url,
        headers=azure_devops_headers(),
        json=payload,
        timeout=30,
    )

    print("AZDO status:", response.status_code)
    print("AZDO content-type:", response.headers.get("Content-Type"))
    print("AZDO body:", response.text[:4000])
    print("AZDO pipeline code branch:", pipeline_branch)
    print("AZDO PR source branch:", source_branch)
    print("AZDO PR target branch:", target_branch)

    if "text/html" in (response.headers.get("Content-Type") or "").lower():
        raise RuntimeError(
            f"Azure DevOps returned HTML instead of JSON. "
            f"Authentication is still failing. status={response.status_code}"
        )

    response.raise_for_status()
    return response.json()


def call_named_agent(conversation_input: str, agent_name: Optional[str]):
    if not agent_name:
        raise RuntimeError("Missing PLAN_RISK_AGENT_NAME in environment variables.")

    agent_reference = find_agent_reference(agent_name)

    client = get_project_client()
    with client.get_openai_client() as openai_client:
        conversation = openai_client.conversations.create(
            items=[{"type": "message", "role": "user", "content": conversation_input}],
        )

        response = openai_client.responses.create(
            conversation=conversation.id,
            extra_body={"agent_reference": agent_reference},
        )

        return getattr(response, "output_text", None) or ""


def extract_json_safely(text: str) -> dict:
    try:
        return extract_json_from_text(text)
    except Exception:
        return {}


def _insert_breaks_for_resource(text: str) -> str:
    if not text:
        return ""
    text = escape(str(text))
    text = text.replace(".", ".<wbr>")
    text = text.replace("/", "/<wbr>")
    text = text.replace("_", "_<wbr>")
    text = text.replace("[", "[<wbr>")
    text = text.replace("]", "]<wbr>")
    text = text.replace("(", "(<wbr>")
    text = text.replace(")", ")<wbr>")
    return text


def _compact_text(value: str, limit: int = 48) -> str:
    if value is None:
        return ""
    value = " ".join(str(value).split())
    if len(value) <= limit:
        return escape(value)
    return escape(value[: limit - 1].rstrip()) + "…"


def _parse_markdown_table(table_md: str) -> list[dict]:
    lines = [line.strip() for line in (table_md or "").splitlines() if line.strip()]
    table_lines = [line for line in lines if line.startswith("|") and line.endswith("|")]

    if len(table_lines) < 2:
        return []

    headers = [cell.strip() for cell in table_lines[0].strip("|").split("|")]
    rows: list[dict] = []

    for line in table_lines[2:]:
        cells = [cell.strip() for cell in line.strip("|").split("|")]
        if len(cells) < len(headers):
            cells += [""] * (len(headers) - len(cells))
        elif len(cells) > len(headers):
            cells = cells[: len(headers)]
        rows.append(dict(zip(headers, cells)))

    return rows


def _render_compact_html_table(headers: list[str], rows: list[list[str]]) -> str:
    if not rows:
        return "<p><em>No data.</em></p>"

    thead = "".join(f"<th>{escape(h)}</th>" for h in headers)
    tbody = []
    for row in rows:
        cols = "".join(f"<td>{cell}</td>" for cell in row)
        tbody.append(f"<tr>{cols}</tr>")

    return (
        "<table>"
        f"<thead><tr>{thead}</tr></thead>"
        f"<tbody>{''.join(tbody)}</tbody>"
        "</table>"
    )


def render_compact_summary_table(summary_markdown: str) -> str:
    parsed = _parse_markdown_table(summary_markdown)
    rows: list[list[str]] = []

    for row in parsed:
        marker = _compact_text(row.get("Marker", ""), 4)
        action = _compact_text(row.get("Action", ""), 12)
        count = _compact_text(row.get("Count", ""), 8)
        resources = row.get("Resources", "") or row.get("Resource", "")

        resource_cells = []
        for part in [r.strip() for r in resources.split(",") if r.strip()]:
            resource_cells.append(_insert_breaks_for_resource(part))

        if not resource_cells:
            resources_html = ""
        elif len(resource_cells) == 1:
            resources_html = resource_cells[0]
        else:
            resources_html = "<br>".join(resource_cells[:6])
            if len(resource_cells) > 6:
                resources_html += "<br>…"

        rows.append([marker, action, count, resources_html])

    return _render_compact_html_table(
        ["", "Act", "Cnt", "Resources"],
        rows,
    )



def render_compact_created_table(created_markdown: str) -> str:
    parsed = _parse_markdown_table(created_markdown)
    rows: list[list[str]] = []

    for row in parsed:
        marker = _compact_text(row.get("Marker", ""), 4)
        resource_name = _insert_breaks_for_resource(row.get("Resource Name", "") or row.get("Resource", ""))
        resource_type = _compact_text(row.get("Type", ""), 24)
        rows.append([marker, resource_name, resource_type])

    return _render_compact_html_table(
        ["", "Resource", "Type"],
        rows,
    )


def render_compact_risk_table(risk_markdown: str) -> str:
    parsed = _parse_markdown_table(risk_markdown)
    rows: list[list[str]] = []

    for row in parsed:
        marker = _compact_text(row.get("Marker", ""), 4)
        resource = _insert_breaks_for_resource(row.get("Resource", "") or row.get("Finding", ""))
        resource_type = _compact_text(row.get("Type", ""), 20)
        action = _compact_text(row.get("Action", ""), 12)
        severity = _compact_text(row.get("Severity", ""), 10)
        risk = _compact_text(row.get("Risk", "") or row.get("Impact", ""), 56)
        rows.append([marker, resource, resource_type, action, severity, risk])

    return _render_compact_html_table(
        ["", "Resource", "Type", "Act", "Sev", "Risk"],
        rows,
    )


def build_plan_risk_agent_input(tfplan: dict, payload: dict) -> dict:
    return {
        "task": "Analyze Terraform plan risk for a pull request.",
        "required_output_format": {
            "headline": "short overall result",
            "summary_markdown": (
                "markdown table with columns Marker | Action | Count | Resources"
            ),
            "created_markdown": (
                "markdown table with columns Marker | Resource Name | Type"
            ),
            "risk_markdown": (
                "markdown table with columns Marker | Resource | Type | Action | Severity | Risk"
            ),
            "overall_risk": "low|medium|high|critical",
        },
        "rules": [
            "Return valid JSON only.",
            "Do not wrap JSON in markdown.",
            "Use these markers consistently: red = 🔴, yellow = 🟡, green = 🟢.",
            "summary_markdown must be a markdown table.",
            "created_markdown must be a markdown table.",
            "risk_markdown must be a markdown table.",
            "Base analysis only on the tfplan payload provided.",
            "Never invent resources or actions not present in the plan.",
            "Keep every table cell concise.",
            "Resource and Finding columns must contain only the exact Terraform resource address or short exact name.",
            "Action must be one of Create, Update, Delete, Replace, No-op when applicable.",
            "Count must be numeric.",
            "Severity must be one of Low, Medium, High, Critical.",
            "Risk must be a short phrase, not a paragraph.",
            "Do not exceed 8 words in any non-resource table cell unless absolutely necessary.",
            "Summary should list grouped resources per action, not long prose.",
            "Created table should list only created resources.",
            "Risk table should include only meaningful risks or high-signal no-op context if needed.",
            "Set overall_risk to the highest real risk present.",
        ],
        "metadata": {
            "repo_owner": payload.get("repo_owner", ""),
            "repo_name": payload.get("repo_name", ""),
            "pr_number": payload.get("pr_number", ""),
            "branch_name": payload.get("branch_name", ""),
            "commit_sha": payload.get("commit_sha", ""),
            "build_id": payload.get("build_id", ""),
            "build_number": payload.get("build_number", ""),
            "module_directory": payload.get("module_directory", ""),
            "folder": payload.get("folder", ""),
        },
        "tfplan": tfplan,
    }


def build_pr_comment_from_agent_result(agent_result: dict, payload: dict) -> str:
    headline = (agent_result.get("headline") or "Terraform plan risk analysis").strip()
    overall_risk = (agent_result.get("overall_risk") or "unknown").strip()

    summary_markdown = (
        agent_result.get("summary_markdown")
        or "| Marker | Action | Count | Resources |\n|---|---|---:|---|\n| 🟡 | Review | 0 | No summary returned |\n"
    ).strip()

    created_markdown = (
        agent_result.get("created_markdown")
        or "| Marker | Resource Name | Type |\n|---|---|---|\n| 🟢 | None | N/A |\n"
    ).strip()

    risk_markdown = (
        agent_result.get("risk_markdown")
        or "| Marker | Resource | Type | Action | Severity | Risk |\n|---|---|---|---|---|---|\n| 🟡 | None | N/A | Review | Medium | No risk table returned |\n"
    ).strip()

    module_directory = payload.get("module_directory", "")
    folder = payload.get("folder", "")
    build_id = payload.get("build_id", "")
    repo_owner = payload.get("repo_owner", "")
    repo_name = payload.get("repo_name", "")
    pr_number = payload.get("pr_number", "")

    summary_html = render_compact_summary_table(summary_markdown)
    created_html = render_compact_created_table(created_markdown)
    risk_html = render_compact_risk_table(risk_markdown)

    return f"""<!-- terrabot-plan-risk-comment -->
## Terrabot Plan-Risk Analysis

**Result:** {escape(headline)}  
**Overall risk:** `{escape(overall_risk)}`  
**Module:** `{escape(module_directory)}`  
**Folder:** `{escape(folder)}`  
**Build ID:** `{escape(str(build_id))}`  
**PR:** `{escape(str(repo_owner))}/{escape(str(repo_name))}#{escape(str(pr_number))}`

<details open>
<summary><strong>Plan Summary</strong></summary>

{summary_html}
</details>

<details open>
<summary><strong>Resources Created</strong></summary>

{created_html}
</details>

<details open>
<summary><strong>Risk Assessment</strong></summary>

{risk_html}
</details>
"""

def load_existing_tf_files_for_context(cloud: str, branch_name: str, folder: str):
    existing = []
    folder_prefix = folder.rstrip("/") + "/"

    def walk(current_path: str):
        for item in github_get_directory_listing(cloud, current_path, branch_name):
            item_type = item.get("type")
            item_path = item.get("path", "")

            if item_type == "dir":
                walk(item_path)
                continue

            if item_type != "file" or not item_path.endswith(".tf"):
                continue

            content = github_get_file_content(cloud, item_path, branch_name)
            if content is None:
                continue

            if item_path.startswith(folder_prefix):
                relative_name = item_path[len(folder_prefix):]
            else:
                relative_name = item_path.split("/")[-1]

            existing.append({
                "filename": relative_name,
                "content": content,
            })

    walk(folder)
    return existing

def ensure_thread_meta(thread_id: str):
    if thread_id not in THREAD_PR_STATE:
        THREAD_PR_STATE[thread_id] = {}

    if "_meta" not in THREAD_PR_STATE[thread_id]:
        THREAD_PR_STATE[thread_id]["_meta"] = {
            "last_selected_cloud": None
        }

    return THREAD_PR_STATE[thread_id]["_meta"]


def set_last_selected_cloud(thread_id: str, cloud: str):
    if not thread_id:
        return
    meta = ensure_thread_meta(thread_id)
    meta["last_selected_cloud"] = cloud



def get_thread_cloud_states(thread_id: str):
    if not thread_id or thread_id not in THREAD_PR_STATE:
        return {}
    return {
        k: v for k, v in THREAD_PR_STATE[thread_id].items()
        if k in ("aws", "azure_module", "azure_consumer", "azure_module_population") and isinstance(v, dict)
    }


def infer_aws_environment_path_from_branch(cloud: str, branch_name: str) -> str | None:
    candidate_roots = [
        "terraform/dev_aws",
        "terraform/prod_aws",
    ]

    best_match = None
    best_depth = -1

    def walk(current_path: str):
        nonlocal best_match, best_depth

        for item in github_get_directory_listing(cloud, current_path, branch_name):
            item_type = item.get("type")
            item_path = item.get("path", "")

            if item_type == "dir":
                walk(item_path)
                continue

            if item_type != "file" or not item_path.endswith(".tf"):
                continue

            if item_path.startswith("terraform/dev_aws/") or item_path.startswith("terraform/prod_aws/"):
                folder = item_path.rsplit("/", 1)[0]
                depth = folder.count("/")
                if depth > best_depth:
                    best_match = folder
                    best_depth = depth

    for root in candidate_roots:
        walk(root)

    return best_match


def recover_cloud_state(thread_id: str, cloud: str, repo_target: Optional[str] = None, workflow: Optional[str] = None):
    cloud = normalize_cloud(cloud)
    repo_target = normalize_repo_target(cloud, repo_target, workflow)
    bucket = state_bucket_for_target(cloud, repo_target, workflow)

    folder = build_stable_folder(thread_id, cloud, repo_target=repo_target, workflow=workflow)
    prefix = build_branch_prefix(thread_id, cloud, repo_target=repo_target, workflow=workflow)
    matching_branches = github_list_matching_branches(cloud, prefix, repo_target=repo_target)

    latest_cycle = 0
    open_pr = None
    latest_pr = None
    selected_branch = None

    for candidate_branch in matching_branches:
        cycle = parse_branch_cycle(candidate_branch, prefix)
        if cycle <= 0:
            continue

        if cycle > latest_cycle:
            latest_cycle = cycle
            selected_branch = candidate_branch

        candidate_open_pr = github_find_pr_by_branch(cloud, candidate_branch, state="open", repo_target=repo_target)
        if candidate_open_pr:
            open_pr = candidate_open_pr
            selected_branch = candidate_branch
            latest_cycle = max(latest_cycle, cycle)
            latest_pr = candidate_open_pr
            break

        candidate_latest_pr = github_find_pr_by_branch(cloud, candidate_branch, state="all", repo_target=repo_target)
        if candidate_latest_pr and (
            latest_pr is None or cycle >= parse_branch_cycle(selected_branch or "", prefix)
        ):
            latest_pr = candidate_latest_pr

    if not selected_branch:
        selected_branch = build_branch_name(thread_id, cloud, 1, repo_target=repo_target, workflow=workflow)
        latest_cycle = 1

    branch_exists = github_branch_exists(cloud, selected_branch, repo_target=repo_target)
    folder_on_base_exists = github_folder_exists(
        cloud,
        folder,
        github_base_branch_for_cloud(cloud, repo_target=repo_target, workflow=workflow),
        repo_target=repo_target,
    )

    if not branch_exists and not open_pr and not latest_pr and not folder_on_base_exists:
        return None

    state = {
        "branch": selected_branch,
        "pr_number": open_pr.get("number") if open_pr else None,
        "pr_url": open_pr.get("html_url") if open_pr else None,
        "cloud": cloud,
        "repo_target": repo_target,
        "state_bucket": bucket,
        "folder": folder,
        "cycle": latest_cycle,
        "has_open_pr": bool(open_pr),
        "latest_pr_state": latest_pr.get("state") if latest_pr else None,
        "latest_pr_merged": bool(latest_pr.get("merged_at")) if latest_pr else False,
    }

    if cloud == "aws" and branch_exists:
        inferred_env_path = infer_aws_environment_path_from_branch(cloud, selected_branch)
        if inferred_env_path:
            state["environment_path"] = inferred_env_path

    return state

def recover_thread_pr_state(thread_id: str) -> dict:
    if not thread_id:
        return {}

    ensure_thread_meta(thread_id)

    existing_thread_state = get_thread_cloud_states(thread_id)
    if existing_thread_state:
        return existing_thread_state

    recovered = {}

    aws_state = recover_cloud_state(thread_id, "aws", repo_target="tf-devops")
    if aws_state:
        recovered["aws"] = aws_state

    azure_module_state = recover_cloud_state(thread_id, "azure", repo_target="vena_repos", workflow="azure_module_repo_creation")
    if azure_module_state:
        recovered["azure_module"] = azure_module_state

    azure_consumer_state = recover_cloud_state(thread_id, "azure", repo_target="tf-azure-hub", workflow="azure_consumer_generation")
    if azure_consumer_state:
        recovered["azure_consumer"] = azure_consumer_state

    if recovered:
        existing_meta = THREAD_PR_STATE.get(thread_id, {}).get("_meta", {"last_selected_cloud": None})
        THREAD_PR_STATE[thread_id] = dict(recovered)
        THREAD_PR_STATE[thread_id]["_meta"] = existing_meta

    return recovered


def is_infra_request(prompt: str, thread_id: Optional[str] = None) -> bool:
    """Deprecated compatibility shim.

    Teams intent is classified exclusively by the Azure AI Foundry agent.
    This function is intentionally non-semantic and must not be used as a
    routing gate. It remains temporarily import-safe for older callers while
    they are upgraded.
    """
    del prompt, thread_id
    return False




